/* ÇEVİRİ en · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("en","olay",{
"OLAYLAR_P0063:1735-05-01:0":{"b": ["The surrender of Baku to Iran", "5c6fa266"], "d": ["Under the Treaty of Ganja's condition of evacuation within two months, the Russian commander de Brilly handed Baku over to Musa Khan, who had come to take the city over.", "68a77e77"]},
"OLAYLAR_P0063:1735-05-08:0":{"b": ["The surrender of Derbent to Iran — the end of thirteen years of Russian occupation", "ad7b20ab"], "d": ["The keys of Derbent were handed over to the Iranian side; some Russian troops remained in the city a little longer. Thus the Russian occupation that began in 1722 ended without a single major battle, owing to Russia's wish to keep Nadir as an ally before a new Ottoman war.", "a72d286a"]},
"OLAYLAR_P0063:1735-07-09:0":{"b": ["The surrender of Ganja to Nadir", "1b50eb22"], "d": ["Nadir, who had defeated the Ottoman army at Arpaçay, a few weeks later captured Ganja, surrounded by strong walls and three moats. The city, which the Ottomans had taken in 1725, became Iranian again; Karabakh was left to Iran by the treaty of 1736.", "03fc4c7d"]},
"OLAYLAR_P0063:1735-08-12:0":{"b": ["Tiflis passed to the Iranian forces", "c463de93"], "d": ["Following Nadir's growth in strength, the Iranian forces retook Tiflis and brought Ali Mirza to the governorship of Kartli-Kakheti. Nadir changed the Ottoman administrative arrangement there; he governed Kartli directly with an Iranian governor, and gave it to Teimuraz in 1744.", "3a18c7c0"]},
"OLAYLAR_P0063:1735-08-23:0":{"b": ["The demolition of the fortress of the Holy Cross — the Russian frontier was drawn back to the Terek, the fortress of Kizlyar was founded", "1bb1117b"], "d": ["After the treaties of Rasht and Ganja, Russia's new frontier became the Terek river; it was decided to demolish the fortress of the Holy Cross on the Sulak, and Levashov reported the demolition in August 1735. In the same year Levashov chose the site of the fortress of Kizlyar on the Terek; the Russian presence on the Dagestan coast, which had continued since 1722, was thus drawn back to the north of the Terek.", "85373e75"]},
"OLAYLAR_P0063:1736-05-02:0":{"b": ["The decision for war with Russia — upon the Russian attack on Azov", "d19f8545"], "d": ["When the Russians attacked the fortress of Azov in Dhu'l-Qa'da 1148 (March 1736) and marched on Or Kapı, the Ottoman government, in a council convened, partly at the instigation of the French ambassador Villeneuve, was obliged to decide on war against Russia. Grand Vizier Seyyid Mehmed Pasha was appointed serasker of the army. Russia had been freed from the Iranian front by the Ganja agreement of March 1735 and had again put the aim of access to the Black Sea on its agenda.", "a65d5ca0"]},
"OLAYLAR_P0063:1736-06-01:0":{"b": ["The surrender of Or Kapı to Münnich — the Russian army entered the Crimea", "af2b2613"], "d": ["Münnich reached the front of the Or Kapı lines on 16 May (Julian) and stormed the lines at dawn on 20 May; the surprised Tatar army withdrew, and the fortress of Or surrendered the next day. The Russian army marched into the interior of the peninsula two days later; Or Kapı remained in Russian hands until the end of August.", "3fec9485"]},
"OLAYLAR_P0063:1736-06-19:0":{"b": ["The surrender of the fortress of Kılburun to Leontiev", "a0600527"], "d": ["As Münnich advanced in the Crimea, the Leontiev column he had detached moved on Kılburun at the mouth of the Dnieper, and the fortress surrendered. Since the source does not give the day on which the Russian forces withdrew from the fortress, the occupation window is not shown on the map.", "c1632ebd"]},
"OLAYLAR_P0063:1736-07-13:0":{"b": ["The fall of Azov to the Russians", "004b5ef1"], "d": ["At the end of the attack that began in March 1736, the fortress of Azov at the mouth of the Don fell into Russian hands. The same summer the Russians crossed Or Kapı and entered the Crimea, took Gözleve and Kılburun, and caused destruction at Bahçesaray and Akmescid. Azov remained in Russia by the peace of 1739, but its fortifications were demolished. The sources differ on the day of the fall: TDV gives this date together with Gözleve, Or Kapı and Kılburun; Russian sources say 19 June (30 June Gregorian), and another source says 1 July.", "fccaab17"]},
"OLAYLAR_P0063:1736-08-27:0":{"b": ["Münnich demolished the Or Kapı line and withdrew from the Crimea", "84ee7e5c"], "d": ["Münnich, who returned to Or Kapı from the interior of the Crimea, stayed here five weeks. Because of shortage of provisions and disease spreading in the army, he had the Perekop fortification line demolished and withdrew to Ukraine; when the Russians left, the Tatars rebuilt the line.", "d453b2eb"]},
"OLAYLAR_P0063:1737-07-14:0":{"b": ["Austria declared war on the Ottomans — a second front alongside Russia", "c27ed99a"], "d": ["Austria, Russia's ally, although peace negotiations had been agreed at Nemirov, attacked Ottoman lands in three columns in June 1737; the emperor's official declaration of war is dated 14 July 1737. Seckendorf took Niš in July, but the Austrian Bosnian operation was halted at Banja Luka in August. This front was closed by Austria's loss in the Treaty of Belgrade of 1739.", "7d5518a3"]},
"OLAYLAR_P0063:1737-07-25:0":{"b": ["Lacy's vanguard took and burned Karasubazar", "ee36541f"], "d": ["Lacy, who entered the Crimea by crossing the Sivash, repelled the khan's attack on 12 July (Julian). Two days later General Douglas, in the vanguard, dispersed the Tatar camp before Karasubazar, took the city without resistance and burned it. Lacy began to withdraw the next day.", "ac1fd466"]},
"OLAYLAR_P0063:1737-07-27:0":{"b": ["The fall of Niš to Austria — Seckendorf's Serbian operation", "084a31e8"], "d": ["The Serbian column of the Austrian army, which entered Ottoman lands in three columns in the summer of 1737, descended south through the Morava valley under Marshal Seckendorf and captured Niš. The fall of the fortress was the only great success of the war in Austria's favor; but in October of the same year the beylerbeyi of Rumelia, Köprülüzâde Hâfız Ahmed Pasha, retook Niš without a fight.", "5fd4065d"]},
"OLAYLAR_P0063:1737-10-16:0":{"b": ["The recapture of Niš from Austria", "265e0917"], "d": ["Niš, which the Austrian army under Seckendorf had taken in Rabî' al-awwal 1150 (July 1737), was retaken in October of the same year by the Beylerbeyi of Rumelia, Köprülüzâde Hâfız Ahmed Pasha. After Banja Luka, this was the second development that frustrated Austria's campaign of 1737.", "2f62abcc"]},
"OLAYLAR_P0063:1738-08-17:0":{"b": ["The capture of Ada Kale from Austria", "24f58282"], "d": ["The Ottoman army, which set out on campaign in the spring of 1738, took Mehadia and besieged Orsova and Ada Kale, crossed the Danube and raided Temesvár. Ada Kale was taken on 17 August 1738. Yeğen Mehmed Pasha, who then came to Niš, launched raids on Belgrade; a year later came the victory of Hisarcık and the Treaty of Belgrade.", "9b408b77"]},
"OLAYLAR_P0065:1770-08-12:0":{"b": ["The Yedisan and Budjak Nogais passed under Russian protection", "54c9791c"], "d": ["While the siege of Bender continued, the Russian commander Panin signed an agreement with the notables of the Yedisan and Budjak Nogai hordes. The Nogais announced that they had separated from the Ottoman State and come under the protection of the Russian empress. About twelve thousand Nogais emigrated from Budjak; the hordes were settled in 1771-1772 on the right bank of the Kuban river. With the passing of the steppes north of the Crimea to the Russian side, the land road to the peninsula was opened.", "8e87da5e"]},
"OLAYLAR_P0065:1771-06-26:0":{"b": ["The Or Kapı line passed to the Russians", "ae464560"], "d": ["The Russian army under Dolgorukov, in a night attack, scaled the left flank of the Or Kapı line with ladders. At the same time Prozorovsky's cavalry crossed the shallows of the Sivash and came out behind the line and dispersed the Crimean-Ottoman cavalry. The next day the fortress garrison surrendered; two days later the Russian army marched into the interior of the peninsula.", "7efec9b9"]},
"OLAYLAR_P0065:1771-06-29:0":{"b": ["The fall of the fortress of Arabat; Kerch, Yenikale and Taman pass into Russian hands", "7784d628"], "d": ["The Russian column under Shcherbatov crossed the Genichesk strait by a bridge built from boats brought by the Azov flotilla, and, marching about a hundred versts along the Arabat spit, took the fortress of Arabat. In July the same column also captured Kerch, Yenikale and Taman. Thus both sides of the Kerch strait came under Russian control.", "5c9efba7"]},
"OLAYLAR_P0067:1788-09-21:0":{"b": ["The battle of Caransebeș — the night withdrawal of the Austrian army", "fcc530d0"], "d": ["The Ottoman forces under the command of Kethüdâ Hasan Pasha, the serasker of Vidin, defeated Joseph II's army at Caransebeș also, after Mehadia. In a council in the tent of the grand vizier-commander it was decided to attack the enemy camp; while preparations continued during the night, the Austrian troops were seen to have abandoned their positions and withdrawn to the town of Caransebeș. The pursuing Ottoman forces pinned them down in the town; in the fire that broke out many soldiers were killed, the survivors took refuge at Lugoj, seven hours away, and more than a thousand people were taken prisoner. The Austrian army's own campaign diary records the same night as a panic and friendly fire; for a comparison of the two sides' accounts, further reading: karsi-karansebes-1788. The city did not come into Ottoman possession: it was taken, burned and abandoned on 10 October 1788 — for this reason no change of frontier appears on the map.", "1b1d8ea5"]},
"OLAYLAR_P0068:1427-01-01:0":{"b": ["Prince Inal united the Kabardians under a single rule", "34f01c9e"], "d": ["Among the Kabardian branch of the Circassians, who had withdrawn eastward after the Mongol-Tatar invasions, Prince Inal (1427-1456) united the greater part of the people under his own rule; the princes of Kabarda, Besleney and Chemguy base their lineage on him. The Kabardian princes until the end of the eighteenth century also had influence over the Chechens, Ingush, Karachay-Balkars and Ossetes and over the Abazas north of the Caucasus mountains. The date is the beginning of Inal's years of rule; the day of the unification is not known.", "405949a2"]},
"OLAYLAR_P0068:1475-01-01:0":{"b": ["The Circassian coast recognized Ottoman sovereignty", "c61a1859"], "d": ["The Genoese colonies on the Black Sea coast, whose connection with the Mediterranean had been cut after the conquest of Constantinople, were taken under Ottoman administration by order of Mehmed the Conqueror, in 1475 by Gedik Ahmed Pasha and in 1479 by Kasım Pasha. The communities living on the shore between Taman and Sochi, whom Ottoman sources call the \"Lower Circassians\", recognized Ottoman sovereignty; the coast thereafter remained under Ottoman sovereignty for three centuries. This is a recognition of sovereignty: the tribes continued their own order, and the places the Ottomans in fact held were coastal fortresses such as Anapa, Sudjuk, Gelincik, Sukhum and Poti.", "b46e4e11"]},
"OLAYLAR_P0068:1563-01-01:0":{"b": ["Russia's first fortress in the Caucasus: Terek", "5dcabb8e"], "d": ["Temryuk, the Kabardian prince, oppressed by Crimean raids and slave raids, sent envoys to Moscow in 1557 and 1559 and married his daughter to Tsar Ivan IV. The Russians, having signed a treaty with some Kabardian princes, founded their first fortress in the Caucasus on the bank of the Terek river in 1563. In a letter he sent in 1570 the Ottoman sultan demanded the demolition of the Russian fortresses in Kabarda; the fortress was demolished in 1574. This is a matter of an alliance and a fortress, not of a change of territorial hands — for this reason it shows no change on the map.", "f74fed71"]},
"OLAYLAR_P0068:1763-01-01:0":{"b": ["Russia built the fortress of Mozdok in Kabarda", "630428b1"], "d": ["In Kabarda, which the Treaty of Belgrade (1739) had left neutral, a struggle had begun between pro-Ottoman and pro-Russian princes. Taking advantage of this confusion, Russia in 1763 had the fortress of Mozdok built on the bank of the Terek, despite the objection of the Ottoman State and of the Kabardian princes. In the following years the fortress became the eastern end of the Russian fortified line extending from Azov to Mozdok and was regarded as one of the causes of the war of 1768-74.", "deaad34c"]},
"OLAYLAR_P0068:1789-10-13:0":{"b": ["Belgrade and Smederevo pass into Austrian hands", "cf874516"], "d": ["In the third year of the war the Austrian commander Loudon took the Ottoman frontier fortresses along the Danube. Smederevo surrendered on 13 October 1789 on condition that the garrison's 300 soldiers leave after laying down their arms; Belgrade, which had been an Ottoman frontier fortress for fifty years, also passed into Austrian hands the same autumn. Between 1789 and 1791 Loudon had entrenchments built commanding the citadel and suburb of Smederevo. Both cities were returned to the Ottoman State by the Treaty of Sistova signed on 4 August 1791; for this reason both are shown on the map as occupation, not annexation. The day of Belgrade's surrender does not appear in any of the four TDV entries read (the entry gives only the year); the date here is the day of Smederevo, and for Belgrade it is not an estimate but the only known day of the same operation.", "3ab6a49a"]},
"OLAYLAR_P0068:1861-06-13:0":{"b": ["The Circassians gathered at Sochi and asked for help from the Ottomans, Britain and France", "d7ae7762"], "d": ["The Circassians, who continued to fight the Russians even after the surrender of Sheikh Shamil (1859), gathered at Sochi on 13 June 1861 and asked for help from the Ottoman State and from Britain and France. No help came; in the same year, with the tsar's approval, the deportation of the Circassians was formally decided, and in 1861-1864 the lands of the Abzakh, Shapsug and Ubykh were occupied. The people were told that within a month they must settle in the places that would be shown to them along the Kuban or emigrate to Ottoman lands, otherwise they would be deported to the interior of Russia as prisoners of war.", "78005fcf"]},
"OLAYLAR_P0068B:1788-01-25:0":{"b": ["The dismissal of Melek Mehmed Pasha from the vizierate — the purge of the peace party", "a07e5755"], "d": ["As the second front of the war was about to open, Melek Mehmed Pasha was dismissed from the vizierate on 25 January 1788. According to TDV the real reason for the dismissal was that Grand Vizier Koca Yûsuf Pasha wished to remove the supporters of peace from the administration of the state. The same man would be appointed grand vizier in 1792, at the end of the war.", "46f1ac86"]},
"OLAYLAR_P0068B:1788-02-22:0":{"b": ["The grand vizier-commander Koca Yûsuf Pasha set out on campaign with absolute authority", "c16ecddb"], "d": ["In the days when the two-front war opened, the grand vizier and commander-in-chief Koca Yûsuf Pasha set out from Istanbul at the head of the army on 22 February 1788. Abdülhamid I gave him, in the words of TDV, a broad independence of the degree of the Köprülüs, that is, absolute authority. The direction and conduct of the war were thus left entirely in the hands of the commander.", "64341325"]},
"OLAYLAR_P0068B:1788-05-10:0":{"b": ["Cezayirli Gazi Hasan Pasha put to sea in the Black Sea with the fleet", "4dc6574c"], "d": ["The kaptan-ı derya Cezayirli Gazi Hasan Pasha put to sea in the Black Sea with the fleet on 10 May 1788. The aim was to exert pressure on the Özi and Kılburun line and to break the superiority of the Russian fleet in the northern Black Sea; this operation was the beginning of the naval engagements that continued through the summer.", "9bc90d70"]},
"OLAYLAR_P0068B:1788-08-01:0":{"b": ["The naval battle of Snake Island (Fidonisi)", "5c6a90c1"], "d": ["Cezayirli Gazi Hasan Pasha defeated the Russian fleet in the battle of Snake Island fought in August 1788. However, this success was not enough to save the fortresses in the northern Black Sea; at the end of the same year Özi fell.", "c850a910"]},
"OLAYLAR_P0068B:1789-01-01:0":{"b": ["The capture of Akkerman by the Russians", "48638c7c"], "d": ["Akkerman was besieged and captured by the Russians in 1789; according to TDV the fortress was falling into Russian hands for the second time since 1770. Tayfur Pasha, who surrendered the fortress without a fight, was executed by the grand vizier Cezayirli Gazi Hasan Pasha.", "3e4f5789"]},
"OLAYLAR_P0068B:1789-05-01:0":{"b": ["The rout at Galați", "65e7a29d"], "d": ["The Ottoman forces were defeated at Galați on 1 May 1789. This rout was the first link in the series of defeats that would be repeated through the summer at Focșani and Rymnik, and it shook the position of the grand vizier-commander Koca Yûsuf Pasha.", "28e100e0"]},
"OLAYLAR_P0068B:1789-06-07:0":{"b": ["The dismissal of Koca Yûsuf Pasha from the grand vizierate", "54fdaa33"], "d": ["The rout at Galați was the visible cause of Koca Yûsuf Pasha's removal from the grand vizierate on 7 June 1789. In his place Kethüdâ Hasan Pasha, known for his successes on the Austrian front, was appointed. In the remaining three years of the war the grand vizierate would change hands four times.", "73d2aab3"]},
"OLAYLAR_P0068B:1789-08-01:0":{"b": ["The rout at Focșani", "09430751"], "d": ["The Ottoman army suffered a heavy defeat at Focșani on 1 August 1789 against the Russo-Austrian forces. Two separate entries of TDV give this day in the same way. The rout would be repeated at Rymnik in September of the same year, and the Ottoman defense in Wallachia would collapse.", "a0cb033c"]},
"OLAYLAR_P0068B:1789-09-22:0":{"b": ["The rout at Rymnik (Boze)", "343edd1a"], "d": ["The Ottoman army suffered a heavy rout on 22 September 1789 while crossing the Rymnik river and then on the bank of the Boza water. This second defeat, coming seven weeks after Focșani, in effect broke up the Wallachian front and led to the surrender of the fortresses on the Dniester line in October-November: the TDV entry on Koca Yûsuf Pasha gives the surrender of Izmail on 11 October and of Bender on 14 November. However, the surrender of Izmail in 1789 does not occur in the TDV entry ismail (the fortress is still in Ottoman hands in 1790), and ESBE also writes that after Rymnik only Hacıbey and Akkerman were taken and that Bender surrendered on 3 November (Julian; = 14 November); TDV akkirman also records that the fortress was taken by the Russians in 1789. The surrender of 11 October is most probably that of Akkerman — since the day could not be confirmed for Akkerman in the source read, it is not shown separately on the map.", "45226358"]},
"OLAYLAR_P0068B:1789-12-03:0":{"b": ["The appointment of Cezayirli Gazi Hasan Pasha as grand vizier and commander-in-chief", "37e10738"], "d": ["After the routs in Wallachia and the loss of fortresses, Cezayirli Gazi Hasan Pasha, the aged commander of the fleet, was appointed grand vizier and commander-in-chief on 3 December 1789. Three separate entries of TDV give this day in the same way. His grand vizierate would last less than four months.", "17c7e52e"]},
"OLAYLAR_P0068B:1790-01-01:0":{"b": ["The landing at Calafat and its repulse", "f8bc2f38"], "d": ["The Ottoman forces that moved from Vidin and landed at Calafat across the Danube at the end of April 1790 were quickly repulsed. This failed landing coincides with the months when the initiative on the Austrian front passed out of Ottoman hands and the search for an armistice began.", "09b57c17"]},
"OLAYLAR_P0068B:1790-03-30:0":{"b": ["The death of the commander-in-chief in the camp at Shumen — the end of a four-month grand vizierate", "ce61597b"], "d": ["The grand vizier and commander-in-chief Cezayirli Gazi Hasan Pasha, over eighty years old, died in the camp at Shumen on 30 March 1790. His grand vizierate, which lasted three months and twenty-eight days, coincided with the harshest winter of the war.", "7ff18e9d"]},
"OLAYLAR_P0068B:1790-04-16:0":{"b": ["The fall of Old Hârșova — the end of a siege that lasted through the winter", "133fe352"], "d": ["After a hard siege that lasted through the winter, Old Hârșova fell into the hands of Austrian forces on 16 April 1790. In the same days the Ottoman side's landing at Calafat from Vidin across the Danube was also repulsed.", "1dcb3252"]},
"OLAYLAR_P0068B:1790-06-08:0":{"b": ["The Austrian forces' descent on Giurgiu and their repulse", "6fbd373f"], "d": ["The Austrian forces descended along the Danube as far as Giurgiu on 8 June 1790, but were repulsed by the Ottoman soldiers. Three months later, in the same place, in the tent of the grand vizier, an armistice with Austria would be signed.", "63725445"]},
"OLAYLAR_P0068B:1790-09-06:0":{"b": ["The decision of the Istanbul consultative council for an armistice — abandonment of the preliminary conditions", "8cb6a44f"], "d": ["The consultative council that met in Istanbul on 6 September 1790 abandoned the preliminary conditions put forward for the negotiations with Austria. This decision cleared the way for the armistice that would be signed twelve days later at Giurgiu and brought about the effective end of the war on the Austrian front.", "f73026d8"]},
"OLAYLAR_P0068B:1790-09-18:0":{"b": ["The Armistice of Giurgiu — the guns fall silent on the Austrian front", "87915031"], "d": ["The armistice between the Ottoman State and Austria was signed in the grand vizier's tent at Giurgiu on Sunday, 18 September 1790. The armistice, which would remain in force for nine months, halted the fighting on the Austrian front that had lasted two and a half years and opened the way for the Sistova peace conference.", "fdf7d652"]},
"OLAYLAR_P0068B:1790-09-21:0":{"b": ["The signing of the Armistice of Giurgiu by Coburg and the exchange of texts", "56ce0fee"], "d": ["The text of the armistice was signed also by the Austrian commander-in-chief Prince Coburg on 21 September 1790, and the copies were handed over reciprocally. Thus the armistice came into force for both sides.", "a6f60a94"]},
"OLAYLAR_P0068B:1790-12-30:0":{"b": ["The opening of the Sistova peace conference", "ce5058cb"], "d": ["The Ottoman and Austrian delegates met for the first time at Sistova on 30 December 1790 and reciprocally presented their credentials. The negotiations, which would last eight months and be completely broken off at one point, thus began.", "407808c4"]},
"OLAYLAR_P0068B:1791-01-01:0":{"b": ["The Russian siege of Brăila — the fortress could not be taken", "a5d5844b"], "d": ["Although the fortress of Brăila was besieged by the Russians in June 1791, it could not be taken. After the rout that took place at Măcin in the same summer, the parties would sit down to an armistice, and Brăila would remain in Ottoman hands.", "367079fa"]},
"OLAYLAR_P0068B:1791-02-27:0":{"b": ["Koca Yûsuf Pasha's second grand vizierate — his taking up office in the camp at Shumen", "c6e04dc4"], "d": ["After the short grand vizierate of Şerif Hasan Pasha, which ended in execution, the seal was given again to Koca Yûsuf Pasha; the pasha went to the camp at Shumen on 27 February 1791 and took up his duty. The armistice and peace negotiations that would end the war would be conducted during his second grand vizierate.", "3331c22b"]},
"OLAYLAR_P0068B:1791-06-10:0":{"b": ["The breaking off of the Sistova negotiations — the withdrawal of the Austrian delegation to Bucharest", "b5a0a875"], "d": ["The Austrian plenipotentiary Herbert withdrew to Bucharest on 10 June 1791 and caused the negotiations to be broken off; the next day the term of the armistice also expired. This rupture lasted five weeks, and the peace was saved only by the intervention of Britain and Prussia.", "19ee29e9"]},
"OLAYLAR_P0068B:1791-06-11:0":{"b": ["The end of the Armistice of Giurgiu — peace squeezed into the same summer", "73e4f9c0"], "d": ["The nine-month Armistice of Giurgiu ended on 11 June 1791. Since the negotiations continuing at Sistova had not been concluded by that day, peace was squeezed between the expiry of the armistice and the possibility of renewed war; the treaty could be signed only on 4 August 1791.", "c0082fb0"]},
"OLAYLAR_P0068B:1791-07-09:0":{"b": ["The rout at Măcin — the defeat that brought peace", "ccadcd46"], "d": ["The Ottoman army suffered a general rout at Măcin and great devastation ensued. This defeat, coming when the armistice with Austria had long since been signed, made the decision to sit down at the table with Russia also unavoidable: an armistice was signed at Galați a month later.", "842dcfca"]},
"OLAYLAR_P0068B:1791-07-18:0":{"b": ["The resumption of the peace negotiations — Herbert's return to Sistova", "3715b815"], "d": ["After the five-week interruption the Austrian delegation returned to Sistova on 18 July 1791. Seventeen days later, on 4 August 1791, the peace treaty would be signed.", "3f3ed300"]},
"OLAYLAR_P0068B:1791-08-08:0":{"b": ["Armistice agreement at Galați between Vâsıf Efendi and Prince Repnin", "f792ca6b"], "d": ["A month after the rout at Măcin, on 8 August 1791, agreement was reached at Galați between Ahmed Vâsıf Efendi and the Russian commander Prince Repnin on the basis of the armistice. Three days later the armistice documents would be signed.", "610110f6"]},
"OLAYLAR_P0068B:1791-08-11:0":{"b": ["The Armistice of Galați — an eight-month ceasefire with Russia", "169ee7ec"], "d": ["An eight-month armistice between the Ottoman State and Russia was signed on 11 August 1791; the documents were ratified the same day under the heading 'essential article and armistice'. The fighting on the Russian front, which had lasted four years, thus ceased, and the framework of the peace that would be signed at Jassy five months later was established.", "6b7fb0e3"]},
"OLAYLAR_P0068B:1791-08-12:0":{"b": ["The ratification of the Treaty of Sistova by the sultan", "8cbbdccd"], "d": ["The Treaty of Sistova, signed on 4 August 1791, was ratified on 12 August. The ratification came the day after the armistice with Russia was signed: the Ottoman State had legally ended the fighting on both fronts within the same week.", "4972648f"]},
"OLAYLAR_P0068B:1791-08-31:0":{"b": ["The ceremonial exchange of the Sistova instruments of ratification", "f8419068"], "d": ["The instruments of ratification of the peace with Austria were exchanged with ceremony on 31 August 1791; after this the grand vizier set out for the peace negotiations on the Russian front. Thus the Austrian front that had opened in 1788 was entirely closed.", "c0ddbdf0"]},
"OLAYLAR_P0068B:1791-10-16:0":{"b": ["The death of Potemkin — the Jassy negotiations changed hands on the Russian side", "78f41463"], "d": ["Potemkin, the Russian plenipotentiary, died on the road on 16 October 1791 while on his way to the Nikolayev Monastery. In his place Count Bezborodko conducted the negotiations; the peace negotiations could begin in an orderly manner only after his arrival, in November.", "ca581195"]},
"OLAYLAR_P0068B:1791-11-10:0":{"b": ["The beginning of the Ottoman-Russian negotiations at Jassy", "455205f8"], "d": ["The Ottoman and Russian delegations held their first session at Jassy on 10 November 1791. Sixteen meetings would be held over two months, and the questions of indemnity and frontiers would be settled in these sessions.", "e092f125"]},
"OLAYLAR_P0068B:1792-01-07:0":{"b": ["The fourteenth session at Jassy — Russia's renunciation of its claim to indemnity", "36aa4c91"], "d": ["At the fourteenth meeting on 7 January 1792 the Russian plenipotentiary Bezborodko gave up the claim to indemnity and declared that peace had been concluded. It was decided that the text of the treaty would be signed three days later.", "76f6232b"]},
"OLAYLAR_P0068B:1792-01-18:0":{"b": ["The ratification of the Treaty of Jassy by the grand vizier's instrument", "b2f4cec8"], "d": ["The Treaty of Jassy, signed on 10 January 1792, was ratified on 18 January by an instrument given by the grand vizier. The ratification would be followed by exchanges of confirmations and instruments of ratification, and the peace would become legally final at the beginning of February.", "be4cae64"]},
"OLAYLAR_P0068B:1792-01-27:0":{"b": ["The sixteenth session at Jassy — the exchange of confirmations", "26061259"], "d": ["At the sixteenth and last meeting held on 27 January 1792 the confirmations were reciprocally exchanged. The conference was thus closed; only the exchange of the sovereigns' instruments of ratification remained.", "6726568b"]},
"OLAYLAR_P0068B:1792-02-10:0":{"b": ["The exchange of the Jassy instruments of ratification — the peace became final in international law", "7b59d6b3"], "d": ["The sovereigns' instruments of ratification were exchanged on 10 February 1792, and the peace acquired finality in terms of the law of nations as well. The five-year, two-front war was thus formally closed; the loss of the Crimea became final and the new frontier of the Ottoman State became the Turla (Dniester).", "f0615309"]},
"OLAYLAR_P0068B:1792-05-03:0":{"b": ["The dismissal of Koca Yûsuf Pasha and his appointment to the governorship of Trabzon", "ee79414b"], "d": ["Three months after the peace became final, Selim III dismissed Koca Yûsuf Pasha, who had been grand vizier twice since the beginning of the war, on 3 May 1792 and on the same day appointed him to the governorship of Trabzon and the guardianship of Anapa. The cadre that had conducted the war thus left office.", "1ff948fd"]},
"OLAYLAR_P0068B:1792-05-04:0":{"b": ["The appointment of Melek Mehmed Pasha to the grand vizierate — the formation of the reform cadre", "bbb92fd7"], "d": ["Melek Mehmed Pasha, who had been removed from the vizierate in 1788 for being pro-peace, was brought to the grand vizierate on 4 May 1792. With his arrival in the capital on 7 June, the collection of memoranda concerning the order of the state (nizâm-ı devlet) from the dignitaries of the state began; the preparation of the Nizâm-ı Cedîd program proceeded with this cadre.", "94e90cff"]},
"OLAYLAR_P0069:1523-01-01:0":{"b": ["The conquest of the fortress of Ostrovica in the Una valley", "5c6cc91b"], "d": ["Ostrovica, held by the Frankopans and other Croatian nobles, stood on a steep ridge linking the northern and southern parts of the Una valley. It passed to Ottoman administration in 1523 and housed an Ottoman garrison until 1878. The fortress gained its real importance after Karlowitz (1699): because of its proximity to the Venetian and Austrian frontier it was enlarged and became the seat of the captaincy of Stara Ostrovica; the town of Kulen Vakuf was founded at its foot at the beginning of the eighteenth century.", "0978b370"]},
"OLAYLAR_P0069:1527-05-01:0":{"b": ["The conquest of the fortresses of Udbina and Krbava — Lika enters Ottoman administration", "5fe329d3"], "d": ["The plain of Krbava had been emptied in 1524, and only Karlović's garrison remained in Udbina. In April 1527 Karlović won a last victory before the fortress, but at the end of May Udbina, together with the fortresses of Mrsinj and Komić, fell into the hands of the pasha of Bosnia. In the same year the Gospić area was given to the Senković aghas. Lika and Krbava thereafter became part of the sancak centred on Obrovac, which took the name Kırka in 1580.", "0e759e1a"]},
"OLAYLAR_P0069:1592-01-01:0":{"b": ["The definitive passing of Drežnik and the županija of Drežnik to Ottoman administration", "6624ad14"], "d": ["Drežnik, held by the Frankopans since 1323, had been held temporarily by the Ottomans in 1578. In 1592 the fortress and the whole županija of Drežnik definitively came under Ottoman administration; Bihać also fell in the same year. In the eighteenth century Drežnik was attached to the captaincy of Ostrožac.", "b41efb59"]},
"OLAYLAR_P0069:1636-01-01:0":{"b": ["The capture of the fortress of Cetin by the Ottomans", "98815f97"], "d": ["Cetin, which had been the key fortress in the defence of the Slunj area against the Ottomans since the middle of the sixteenth century, passed to Ottoman administration in 1636 after repeated sieges. This first Ottoman period lasted two years.", "44a52e6e"]},
"OLAYLAR_P0069:1638-01-01:0":{"b": ["The return of the fortress of Cetin to the Habsburg side", "690f9f84"], "d": ["Cetin, which had passed into Ottoman hands in 1636, returned in 1638 to the Croatian–Habsburg frontier defence and remained so until 1670.", "8f16b3ec"]},
"OLAYLAR_P0069:1670-01-01:0":{"b": ["Cetin again became an Ottoman fortress", "e1750675"], "d": ["In 1670 Cetin again became an Ottoman fortress and was substantially fortified in the eighteenth century: the medieval fortress was surrounded with bastioned walls. Until 1790 the fortress held the northwestern extremity of the Bosnian frontier.", "3cf8713d"]},
"OLAYLAR_P0069:1689-01-01:0":{"b": ["The loss of Lika and Krbava — Udbina and Gospić passed into the hands of the Habsburg frontier forces", "01277a38"], "d": ["In the war that continued after the Vienna debacle, the Croatian frontier troops under Herberstein, general of Karlovac, took Udbina in 1689; Gospić also left Ottoman administration in the same year. Ottoman Lika, which had lasted more than 160 years, came to an end, the emptied lands were settled with a new Croatian population, and Udbina became an important fortress of frontier defence against the Ottomans until the Peace of Sistova (1791).", "bde1a0dc"]},
"OLAYLAR_P0069:1788-01-01:0":{"b": ["The capture of Drežnik by Austria — the western front of the Dubica War", "05d5e5f1"], "d": ["In the Ottoman–Austrian war of 1788–1791, Habsburg forces took Drežnik, to the west of Bihać. By Article 4 of the Treaty of Sistova, Drežnik and Cetin remained under Habsburg administration and never returned to Bosnia.", "30f8f200"]},
"OLAYLAR_P0069:1790-01-01:0":{"b": ["The capture of the fortress of Cetin by Austria", "df182480"], "d": ["In 1790 the Habsburg army attacked Cetin, Bužim and Velika Kladuša and took Cetin. The mobilization declared by the governor of Bosnia and the counter-offensive failed to retake the fortress; Article 4 of the Treaty of Sistova ceded Cetin to the Habsburgs. The frontiersmen of Bosnia recaptured the fortress in brief raids in 1809 and 1813.", "fc69baec"]},
"OLAYLAR_P0917DUNYA:1915-02-23:0":{"b": ["The Russian occupation of Hopa", "d4bd9ae3"], "d": ["Hopa, which after the Treaty of Berlin of 1878 had remained an Ottoman kaza in the sancak of Lazistan, was occupied by Russian troops in the First World War; the occupation lasted until 14 March 1918.", "4cbc2764"]},
"OLAYLAR_P0917DUNYA:1915-09-26:0":{"b": ["The British occupation of Kut al-Amara", "2447347a"], "d": ["The British General Townshend, aiming to take Baghdad, moved along the Tigris and occupied Kut al-Amara on the way. The city again passed into the hands of Turkish forces after the surrender protocol signed on 29 April 1916.", "f815cd30"]},
"OLAYLAR_P0917DUNYA:1916-02-16:0":{"b": ["The fall of Erzurum to Russian occupation", "4bcf972b"], "d": ["The Russian forces, which since the beginning of the war had chosen Erzurum as their chief objective, entered the city; Erzurum came under Russian occupation for the third time. The occupation lasted until 12 March 1918.", "65611111"]},
"OLAYLAR_P0917DUNYA:1916-02-24:0":{"b": ["The Russian occupation of Aşkale", "c0b4232f"], "d": ["The Russian forces, who had taken Erzurum on 16 February 1916, advanced westward and occupied Aşkale on 24 February. Aşkale was liberated on 3 March 1918.", "6b05668a"]},
"OLAYLAR_P0917DUNYA:1916-03-01:0":{"b": ["The Russian occupation of Bitlis", "2cdb1cbc"], "d": ["Russian forces occupied Bitlis. The occupation lasted until 8 August 1916.", "b311d03c"]},
"OLAYLAR_P0917DUNYA:1916-03-08:0":{"b": ["The Russian occupation of Rize: the fall of the eastern Black Sea coast", "263f36d3"], "d": ["The Russian troops, who went on the offensive from Batum in the direction of Arhavi on 7 February 1916, advanced westward along the coast and occupied Pazar on 4 March, Çayeli on 5 March, Rize on 8 March and Of on 26 March. Trabzon was taken by land at the end of this advance, on 18 April 1916.", "5edb2835"]},
"OLAYLAR_P0917DUNYA:1916-04-18:0":{"b": ["The Russian occupation of Trabzon", "5d166ea1"], "d": ["The Russian troops, who broke through the defensive line at Karadere on 14 April and reached Yomra on 16 April, entered Trabzon on 18 April after the Turkish population had evacuated the city. The Russian occupation lasted until 24 February 1918.", "311840b1"]},
"OLAYLAR_P0917DUNYA:1916-07-16:0":{"b": ["The Russian occupation of Bayburt and Gümüşhane", "a4229eff"], "d": ["With the breaking of the Kop defense, Russian troops occupied Bayburt on 16 July 1916, Gümüşhane on 19 July and Kelkit on 22 July; Erzincan fell after these, on 24 July.", "04312d2b"]},
"OLAYLAR_P0917DUNYA:1916-07-24:0":{"b": ["The Russian occupation of Erzincan", "81c11c05"], "d": ["Russian forces occupied Erzincan on 24 July 1916. The city was liberated on 26 February 1918.", "964bb144"]},
"OLAYLAR_P0917DUNYA:1916-08-08:0":{"b": ["The liberation of Bitlis from Russian occupation", "8294f009"], "d": ["The Russian occupation that began on 1 March 1916 ended with the withdrawal of the Russians from the city.", "d172c696"]},
"OLAYLAR_P0917DUNYA:1916-09-17:0":{"b": ["Ta'if passed to the forces of Sharif Hussein", "3924f74f"], "d": ["During the First World War the forces of Sharif Hussein, who had risen against Ottoman rule and was supported by the British, captured Ta'if. The city suffered great damage during the siege.", "77eb751d"]},
"OLAYLAR_P0917DUNYA:1916-11-06:0":{"b": ["The killing of Ali Dinar — the Sultanate of Darfur came to an end, Darfur was attached to British Sudan", "17796ae7"], "d": ["Ali Dinar, the Sultan of Darfur, who had drawn close to the Ottoman State in the First World War, had withdrawn in the direction of Jebel Marra after the fall of his capital El Fasher in May 1916; he was killed on 6 November 1916 by forces sent by the Sudan government. Some time later the lands of Darfur were attached to British Sudan as a province.", "77fea96b"]},
"OLAYLAR_P0917DUNYA:1917-03-07:0":{"b": ["The British occupation of Najaf", "eff495f9"], "d": ["Najaf, which in the last period of the Ottomans was a kaza center attached to the sancak of Karbala in the vilayet of Baghdad, was occupied by the British on 7 March 1917; four days later Baghdad also fell. In 1920 the city was included within the boundaries of Iraq with the monarchy founded.", "737a90d9"]},
"OLAYLAR_P0917DUNYA:1917-12-06:0":{"b": ["Khanaqin entered the British line", "daef063a"], "d": ["After the Hamrin operation, the British III Corps settled on 6 December 1917 on an advanced line extending from Khanaqin to Qizil Ribat; Khanaqin remained thereafter in British hands and became the head of the road to Iran.", "968eb7b5"]},
"OLAYLAR_P0917DUNYA:1918-02-19:0":{"b": ["The liberation of Bayburt and Gümüşhane", "15162c86"], "d": ["In the advance that began with the abrogation of the Armistice of Erzincan, Kelkit was liberated on 17 February and Bayburt on 19 February; the Russian occupation of Gümüşhane ended on 28 February 1918.", "6ac1cb20"]},
"OLAYLAR_P0917DUNYA:1918-02-24:0":{"b": ["The liberation of Trabzon from Russian occupation", "d0c44c85"], "d": ["The Russians withdrew from Trabzon and the occupation, which had lasted about two years, came to an end.", "7a57114d"]},
"OLAYLAR_P0917DUNYA:1918-02-26:0":{"b": ["The liberation of Erzincan", "2700373c"], "d": ["Erzincan, which had been under Russian occupation since 24 July 1916, was liberated by Turkish units.", "d3617b82"]},
"OLAYLAR_P0917DUNYA:1918-03-02:0":{"b": ["The liberation of Rize: the recovery of the eastern Black Sea coast", "cab60e94"], "d": ["With the withdrawal of the Russians, Turkish troops advanced eastward along the coast: Rize came again under Ottoman administration on 2 March, Çayeli on 9 March and Hopa on 14 March 1918.", "014dea28"]},
"OLAYLAR_P0917DUNYA:1918-03-12:0":{"b": ["The liberation of Erzurum", "6c832f86"], "d": ["Turkish units under the command of Kâzım Karabekir Pasha freed Erzurum from Armenian units; after two years of occupation the city again came under Ottoman administration.", "43ae103d"]},
"OLAYLAR_P0917DUNYA:1918-04-01:0":{"b": ["The rout at Tuz Khurmatu — Ottoman troops withdrew to Kirkuk", "d844b61f"], "d": ["Toward the end of the First World War, the Ottoman troops, defeated by British forces at Tuz Khurmatu in April 1918, withdrew to Kirkuk; the town came under British occupation.", "07529ee4"]},
"OLAYLAR_P0917DUNYA:1918-04-28:0":{"b": ["Southern Kurdistan operation: Column C entered Kifri", "13b40542"], "d": ["In the Southern Kurdistan operation the British Column C entered Kifri on the morning of 28 April 1918 without resistance. When Kirkuk was abandoned at the end of May, Kifri and Tuz Khurmatu were also held as British forward outposts.", "bcae14d1"]},
"OLAYLAR_P0917DUNYA:1918-05-07:0":{"b": ["The British occupation of Kirkuk", "6f7a899f"], "d": ["The Ottoman troops, routed at Tuz Khurmatu in April 1918, withdrew to Kirkuk; on 7 May the British occupied Kirkuk.", "dd627ad7"]},
"OLAYLAR_P0917DUNYA:1918-05-27:0":{"b": ["The recapture of Kirkuk", "9e911edf"], "d": ["After a British occupation lasting twenty days, Kirkuk was retaken by Ottoman forces on 27 May 1918. The city passed again to British administration when, upon the British attacks that began on 28 October 1918, the Ottoman troops withdrew to Altun Kupri.", "08a1b3e0"]},
"OLAYLAR_P0917DUNYA:1918-07-12:0":{"b": ["End of the Samarra railway: a British detachment settled at Tikrit", "7015ab60"], "d": ["After the battle of Tikrit on 5 November 1917, the British forces had withdrawn to Samarra on 10 November. On 12 July 1918 a detachment from I Corps occupied Tikrit to protect the extension of the Samarra railway.", "baff356d"]},
"OLAYLAR_P0917DUNYA:1918-09-15:0":{"b": ["The Army of Islam of the Caucasus captured Baku", "1ac40958"], "d": ["The Army of Islam of the Caucasus under the command of Nuri Pasha, which had come to the aid of the Democratic Republic of Azerbaijan in accordance with the Treaty of Batum of 4 June 1918, captured Baku, which was in Russian hands. After the Armistice of Mudros the Ottoman forces withdrew from the city; the republic came to an end on 27 April 1920 with the occupation by the Red Army.", "31413075"]},
"OLAYLAR_P0917DUNYA:1921-02-25:0":{"b": ["The Red Army's entry into Tiflis: the fall of the Democratic Republic of Georgia", "de0e19cd"], "d": ["Georgia, which had declared its independence on 26 May 1918, was occupied by Soviet Russia in February 1921; on 25 February 1921 the Bolsheviks entered Tiflis and established the Soviet regime.", "bb1f8870"]},
"OLAYLAR_P0917KOSU13:1387-01-01:0":{"b": ["The conquest of Vodina (winter of 1386-1387)", "1e542d14"], "d": ["Vodina in Macedonia, west of the Vardar, came under Ottoman administration through a conquest for which the Ottoman chronicles give different years. Hoca Sâdeddin places the conquest in 1386; TDV finds it more appropriate, with strong probability, to accept the winter of 1386-1387. Since the commander who made the conquest is not expressly named in the source, no person has been written.", "0da93b6a"]},
"OLAYLAR_P0917KOSU13:1415-01-01:0":{"b": ["Manisa came under the administration of Çelebi Mehmed — the end of the Manisa branch of the Saruhanids", "6d6c7622"], "d": ["At the end of the Interregnum, the land of Saruhan came under the administration of Çelebi Mehmed and the Manisa branch of the Saruhanids passed into history. TDV places this transfer after 1411 and before 1415; Ottoman administration could be fully established shortly before 818 (1415). The date has therefore been written with the latest end of the range.", "4d3e8c85"]},
"OLAYLAR_P0917KOSU13:1427-01-01:0":{"b": ["Yergöğü passes to Wallachia", "bc5c11f4"], "d": ["The fortress of Yergöğü (Giurgiu) on the Danube bank was retaken by the Wallachians in 1427. The fortress, one of the Ottomans' first footholds on the northern bank of the Danube, remained in Wallachia for more than twenty years.", "91dc683d"]},
"OLAYLAR_P0917KOSU13:1450-01-01:0":{"b": ["Yergöğü comes again under Ottoman control (853/1449-50)", "c9ad1b89"], "d": ["The fortress of Yergöğü, which the Wallachians had retaken in 1427, came again under Ottoman control in the year 853. Since the Hijri year extends from February 1449 to February 1450, the date was written as the beginning of 1450, which falls within the range. The fortress thereafter became an Ottoman frontier post guarding the Danube crossing.", "15b80685"]},
"OLAYLAR_P0917KOSU13:1516-10-01:0":{"b": ["Jerusalem and the cities of Palestine come under Ottoman rule", "7ac58e9d"], "d": ["After the victory of Marj Dabiq, with Selim the Grim's arrival at Damascus on 27 September, the cities of Syria and Palestine passed one after another under Ottoman rule. TDV states that Nablus came under Ottoman rule in the autumn of 1516 and Jerusalem probably in October 1516, before the sultan's arrival. The sultan came to Jerusalem only after the battle of Gaza, on 29 December 1516.", "7680d172"]},
"OLAYLAR_P0917KOSU13:1532-01-01:0":{"b": ["Bitlis passed under Safavid protection — Ulama and Fil Pasha lifted the siege", "2d0610f6"], "d": ["When Tekelü Ulama took refuge with the Ottomans and was appointed beylerbeyi over the land of Bitlis, Şeref Khan, the Ottoman-subject ruler of Bitlis, took refuge with the Safavids. Ulama and Fil Pasha, the Beylerbeyi of Diyarbekir, besieged the fortress in the year 938; the fortress held out for three months, and the Ottoman forces, learning that Shah Tahmasb was approaching, lifted the siege. The Shah attached Bitlis and the districts of Ahlat, Muş and Hınıs to Şeref Khan.", "8b605ee5"]},
"OLAYLAR_P0917KOSU13:1534-01-01:0":{"b": ["Bitlis was finally joined to the Ottomans by the hand of Ulama Pasha", "7631002a"], "d": ["Tekelü Ulama, whose first siege had been inconclusive, killed Şeref Khan, the ruler of Bitlis, in 940 (1533) and in 1534 definitively annexed Bitlis to Ottoman lands. Şemseddin Bey, Şeref Khan's son, after Bitlis was given to Ulama, fled to the Safavids with the Rojeki tribe. Ottoman dominion over Bitlis was also recognized by the Safavids in the Treaty of Amasya of 1555.", "3d1f3e99"]},
"OLAYLAR_P0917KOSU13:1565-01-01:0":{"b": ["The capture of the fortress of Krupa by the Ottomans", "7a786bf3"], "d": ["The fortress of Krupa on the right bank of the Una fell into Ottoman hands in 1565. In the following two centuries the fortress remained Ottoman against Austrian sieges (1581, 1690, 1692, 1716) and was part of the Una frontier line between Bihać and Novi.", "e7a52e35"]},
"OLAYLAR_P0917KOSU13:1578-08-24:0":{"b": ["The capture of Tiflis without a fight — the submission of Kakheti and Imereti", "b1563ee6"], "d": ["The Ottoman army under Lala Mustafa Pasha, advancing after the victory of Çıldır, reached Tiflis on 24 August and took the evacuated fortress without a fight. After the conquest of Tiflis the rulers of Imereti and Kakheti announced their submission to the Ottomans.", "41a9cb07"]},
"OLAYLAR_P0917KOSU13:1588-09-01:0":{"b": ["The submission of Şâhverdi Khan, ruler of Qaradagh (Ahar), to Cafer Pasha — Marand comes under Ottoman administration", "fe55fb37"], "d": ["Cafer Pasha, the Beylerbeyi of Tabriz, extended his rule to Marand in 1588; Şâhverdi Khan, the ruler of Qaradagh, submitted and sent his son to Tabriz. The sources give only the year; the day has been matched with the Ganja campaign of the same year.", "9a1a0cee"]},
"OLAYLAR_P0917KOSU13:1589-01-01:0":{"b": ["Cığalazâde Sinan Pasha took Nihavand and built a fortress — the submission of Luristan", "1a6a0329"], "d": ["Cığalazâde Sinan Pasha, the governor of Baghdad, took Nihavand at the end of the year 1588 and had a fortress built there; Şâhverdi, the ruler of Luristan, submitted to the Ottomans. The sources give no day; the date is at the year level.", "89a4eefd"]},
"OLAYLAR_P0917KOSU13:1722-11-01:0":{"b": ["Ottoman recognition of Hajji Dâvud's rule over Shirvan", "8e7b0476"], "d": ["In November 1722, while the Ottomans were giving the Russian forces an ultimatum to withdraw from the region, they recognized Hajji Dâvud's rule over Shirvan. Hajji Dâvud thus became a vassal ruler dependent on the Ottomans, like the khan of the Crimea.", "6b466aaf"]},
"OLAYLAR_P0917KOSU13:1723-08-06:0":{"b": ["The Russian capture of Baku", "482170dc"], "d": ["In the second year of Peter I's Caspian campaign, General Matyushkin's force came by sea and captured Baku. The city remained under a Russian garrison until it was returned to Iran in 1735 by the Treaty of Ganja. The TDV entry on Baku places the return in 1734; Russian and Iranian sources give the Treaty of Ganja of 1735.", "29dc4fb3"]},
"OLAYLAR_P0917KOSU13:1723-11-10:0":{"b": ["The surrender of Sanandaj (Sine), the center of Ardalan", "83b23183"], "d": ["Hane Mehmed Pasha, the Baban bey sent against Ardalan after the capture of Kermanshah, took over Sanandaj, the center of the province; the liwas of Mihribân (Merivan), Bâne and Sakız were also joined to the Ottoman province of Ardalan. In 1727 a detailed Ottoman tahrir register was compiled for the province.", "e4060148"]},
"OLAYLAR_P0917KOSU13:1724-01-01:0":{"b": ["Urmia and Salmas passed to Ottoman administration", "1e25828f"], "d": ["In the years when the Safavid State was dissolving through the Afghan invasion, Urmia once more came under Ottoman dominion. In 1728 an Ottoman tahrir register was compiled for Urmia and the liwa of Salmas attached to it. In Nadir's offensive of 1729-1730 the region was lost; Hekimoğlu Ali Pasha retook Urmia in 1731.", "505c034f"]},
"OLAYLAR_P0917KOSU13:1725-09-09:0":{"b": ["The capture of Ardabil", "917ebe96"], "d": ["After Tabriz, the forces of Köprülüzâde Abdullah Pasha entered Ardabil, the spiritual center of the Safavids. In 1728 the city was registered as the Ottoman liwa of Ardabil, together with the nahiyes of Serab and Miyane; the neighboring Halkhal was also entered in the register as a separate liwa. Nadir retook Ardabil in 1730.", "1fe99397"]},
"OLAYLAR_P0917KOSU13:1731-11-15:0":{"b": ["Hekimoğlu Ali Pasha retook Tabriz", "fda463ac"], "d": ["Hekimoğlu Ali Pasha retook Tabriz, which had fallen into Safavid hands in 1730, on 15 November 1731; Urmia had also been taken in the same operation. However, by the agreement made on 10 January 1732 Tabriz was left to Iran.", "f5c5e134"]},
"OLAYLAR_P0917KOSU13:1735-10-03:0":{"b": ["The surrender of Revan to Nadir Khan", "371ef64b"], "d": ["Nadir Khan, who after the rout at Arpaçay (Baghavard) had taken Ganja on 9 July and Tiflis on 12 August, captured Revan as well. The nahiyes of Karpi (Üçkilise), Şerür and Maku also passed to Iran together with the provincial center.", "d2c03da0"]},
"OLAYLAR_P0917KOSU13:1736-03-24:0":{"b": ["Russia marched on Azov and the Crimea — the Ottoman-Russian War in effect began", "c6d4dbc7"], "d": ["Russia, which regarded the Crimean forces' passage through Kabarda on the way to the Iranian front as a violation of its territory, used this as a pretext and, without declaring war, marched on Azov and the Crimea in two columns. Münnich crossed the Don and took the fortresses before Azov. The Ottoman divan took the decision for war only on 2 May 1736.", "c7d0e549"]},
"OLAYLAR_P0917KOSU13:1739-12-12:0":{"b": ["The ahidname of the peace with Russia: Kabarda neutral, Azov to be demolished", "27454835"], "d": ["The ahidname of the peace with Russia was drawn up on 12 December 1739. The fortifications of Azov were to be demolished and an empty buffer zone left between the two states; Kabarda was to be dependent neither on Russia nor on the Ottomans (art. 6). Özi and Kılburun were left to the Ottomans.", "02e73b3a"]},
"OLAYLAR_P0917KOSU13:1770-09-01:0":{"b": ["The surrender of the fortress of Kilia to Repnin", "e894b7d0"], "d": ["The column of Repnin, which descended to the mouth of the Danube after the rout at Kartal, came before Kilia on 10 August (Julian). After the fire of the breaching batteries and a ten-day defense, the garrison surrendered the fortress on condition that they leave freely with their arms and the goods of the people. Kilia was returned to the Ottomans by the Treaty of Küçük Kaynarca (1774).", "fb66a9e9"]},
"OLAYLAR_P0917KOSU13:1770-10-09:0":{"b": ["The fortress of Akkerman at the mouth of the Dniester fell", "018c420b"], "d": ["Shortly after the fall of Bender, Akkerman at the mouth of the Dniester also fell into the hands of the Russian forces. The fortress was returned to the Ottomans by the Treaty of Küçük Kaynarca (1774).", "38e48332"]},
"OLAYLAR_P0917KOSU13:1788-08-26:0":{"b": ["The fall of Dubica to Austria", "66d70917"], "d": ["The first Austrian attacks in the spring of 1788 had been repulsed. In August Marshal Laudon re-established the siege; the fortress, whose food and ammunition had run out, surrendered on 26 August 1788. Dubica, together with Novi, which fell in October, was Austria's only military success that year. The fortress was returned to the Ottomans by the Treaty of Sistova of 1791.", "658f6f5a"]},
"OLAYLAR_P0917KOSU13:1788-09-01:0":{"b": ["The capture of Khotin by Austro-Russian forces", "a6c18567"], "d": ["In the war that began in 1787, the combined forces of Austria and Russia besieged Khotin, and the fortress was taken by these forces in September 1788. According to the Treaty of Sistova, Austria held the fortress in trust until the end of the Russian peace; Khotin was returned to the Ottomans by the Treaty of Jassy of 1792.", "59f8979f"]},
"OLAYLAR_P0917KOSU13:1788-10-03:0":{"b": ["Laudon took the fortress of Novi on the Una", "80651c30"], "d": ["After Dubica, Laudon marched on the fortress of Novi on the Una and took it on 3 October 1788; the kapudan Cerić and all the garrison were taken prisoner. Upon the loss of the two fortresses a general mobilization was proclaimed in Bosnia. Novi was returned by the Treaty of Sistova of 1791.", "36ddff90"]},
"OLAYLAR_P0917KOSU13:1789-11-01:0":{"b": ["The occupation of Bucharest by the Austrian army (Coburg)", "ec890b9a"], "d": ["After the defeat at Rymnik, the Austrian army occupied Bucharest, the center of Wallachia, at the beginning of November 1789. The city was returned to the Ottoman side by the Treaty of Sistova on 4 August 1791.", "8c031b96"]},
"OLAYLAR_P0917KOSU13:1789-11-14:0":{"b": ["The surrender of the fortress of Bender to Potemkin", "a661bafa"], "d": ["In the Ottoman-Russian war of 1787-1792, the fortress of Bender on the Dniester surrendered to the Russian army under Potemkin's command. The fortress was returned to the Ottomans by the Treaty of Jassy of 1792.", "b150e1c5"]},
"OLAYLAR_P0917KOSU13:1790-10-24:0":{"b": ["The surrender of the fortress of Kilia to the Russians", "5e88acfe"], "d": ["In the campaign of 1790 the fortress of Kilia at the mouth of the Danube was besieged on 4 October (old style) and nine days later surrendered to General Gudovich. The fortress was returned to the Ottomans by the Treaty of Jassy of 1792.", "45089b90"]},
"OLAYLAR_P0917KOSU13:1809-09-26:0":{"b": ["The surrender of the fortress of Izmail to General Zass", "dc74c6d0"], "d": ["During the Ottoman-Russian war of 1806-1812 the fortress of Izmail on the Danube surrendered to General Zass. The fortress was ceded to Russia, together with Bessarabia, by the Treaty of Bucharest of 1812.", "4d43c35c"]},
"OLAYLAR_P0917KOSU13:1838-01-01:0":{"b": ["The Russians took the ports of Sochi and Tuapse on the Circassian coast", "75679594"], "d": ["On the coast of the Circassians, who did not recognize the Treaty of Edirne and remained in effect independent, the Russians took the ports of Sochi and Tuapse in 1838. The occupation of the Circassian interior was completed in 1861-1864.", "36d3e541"]},
"OLAYLAR_P0917KOSU13:1854-01-01:0":{"b": ["In the Crimean War the Russians evacuated and blew up the Velyaminovsky fortress at Tuapse", "2202f051"], "d": ["With the entry of the Anglo-French fleet into the Black Sea in the Crimean War, the Russian fortresses on the Circassian coast, which had become indefensible, were evacuated; the Velyaminovsky fortress, founded at Tuapse in 1838, was also abandoned and blown up. The coast remained for about ten years again under the control of the Circassian tribes.", "2b772139"]},
"OLAYLAR_P0917KOSU13:1864-02-01:0":{"b": ["The Russians retook the old Velyaminovsky fortress at Tuapse", "a7ca0939"], "d": ["In the last year of the occupation of the western Caucasus, Russian troops landed on the Circassian coast and again occupied the site of the Velyaminovsky fortress evacuated ten years before. Within a few months Circassian resistance came to an end, and the people of the coast were for the most part deported to Ottoman lands.", "12049c51"]},
"OLAYLAR_P0917TARAF:1886-01-01:0":{"b": ["Franco-Ottoman arrangement — the coastal section of the boundary between Tunisia and Tripolitania was drawn", "52a273ad"], "d": ["Five years after Tunisia came under French protection in 1881, France and the Ottoman State fixed the boundary between Tunisia and the vilayet of Tripolitania for a short distance, starting from the Mediterranean coast. The source gives only the year; the coordinates of the line are not known.", "ef857ca6"]},
"OLAYLAR_P0917TARAF:1892-01-01:0":{"b": ["Second Franco-Ottoman arrangement — the Tunisia-Tripolitania boundary was extended to Ghadames", "94885487"], "d": ["A second Franco-Ottoman arrangement determined the boundary between Tunisia and the vilayet of Tripolitania in more detail than before and in the interior as far as Ghadames. The actual document that drew today's boundary is the Convention of Tripoli, to be signed eighteen years later.", "b9df9291"]},
"OLAYLAR_P0917TARAF:1906-10-01:0":{"b": ["Rafah Agreement — the Rafah-Taba line between the Ottomans and the Khedivate of Egypt was described", "f10d25c6"], "d": ["After the Aqaba-Taba crisis of 1906, Ottoman and Khedivial commissioners agreed at Rafah on an administrative dividing line; the line extended from Ras Taba on the Gulf of Aqaba to the middle of the two pillars at Rafah. The mixed commission set up ninety-one masonry pillars along the line between the end of the same year and February of the next. This line is today's Egypt-Israel and Egypt-Gaza border.", "28a925f5"]},
"OLAYLAR_P0917TARAF:1909-04-19:0":{"b": ["Turco-Bulgarian Protocol in Istanbul — the Ottomans recognized the independence of Bulgaria", "97302dc1"], "d": ["By the protocol signed in Istanbul through Russia's mediation, the Ottoman State officially recognized the independence of Bulgaria, which had been declared unilaterally six months earlier. Thus the old Ottoman-Bulgarian frontier in Strandzha (Istranca) legally also became the line between two independent states; this section is still part of the Turkey-Bulgaria border today.", "393405ba"]},
"OLAYLAR_P0917TARAF:1910-05-19:0":{"b": ["Convention of Tripoli — the boundary between Tunisia and the vilayet of Tripolitania was drawn from Ras Ajdir to Ghadames", "9ca9e95a"], "d": ["The convention signed at Tripoli between France and the Ottoman State described the boundary between Tunisia and the vilayet of Tripolitania from Ras Ajdir on the Mediterranean coast to the south of Ghadames. The mixed commission marked the line with more than two hundred stones in 1910-1911; the line is still the Libya-Tunisia border today. Two years later this boundary passed from the Ottomans to Italy by the Treaty of Ouchy.", "74a4bc3f"]},
"OLAYLAR_P0917TARAF:1913-11-17:0":{"b": ["Istanbul Protocol — the delimitation of the Turco-Iranian frontier", "daa100b9"], "d": ["Ottoman and Iranian representatives, under the supervision of the British and Russian ambassadors, signed in Istanbul the protocol for the delimitation of the Turco-Iranian frontier based on the Treaty of Erzurum of 1847. The mixed commission marked the line on the ground until October of the following year, except for a short section around Kotur. This line, which remained the Turkey-Iran frontier in 1923, was changed in three sections in 1932 and 1937.", "4bb44a7b"]},
"OLAYLAR_P0917TARAF:1915-09-06:0":{"b": ["Sofia Convention — rectification of the Ottoman-Bulgarian frontier", "42026201"], "d": ["The convention signed in Sofia shortly before Bulgaria's entry into the war on the Ottoman side rectified the Ottoman-Bulgarian frontier drawn by the Treaty of Istanbul of 1913. The Eastern Thrace section of the line was re-marked in 1921 by the Neuilly commission and confirmed at Lausanne.", "b259b598"]},
"OLAYLAR_SEHIR_ILK:1284-03-20:0":{"b": ["Bilecik is first mentioned — the border with Byzantium began at Bilecik", "7b69f743"], "d": ["In the events of the year 683 reported by Neşrî, Bilecik appears as the place where the border between the frontier principality of Osman Bey and Byzantium began. This is the first known mention of the settlement in history; it is not its foundation.", "f668b296"]},
"OLAYLAR_SEHIR_ILK:1299-09-28:0":{"b": ["A coin in the name of Ghazan Khan at Burdur — the city's first known testimony", "01974ddc"], "d": ["The Hamidids, under Ilkhanid pressure, were forced in the year 699 to have a coin struck at Burdur in the name of Ghazan Khan. This coin is the first written/dated testimony to Burdur.", "83a1e1ee"]},
"OLAYLAR_SEHIR_ILK:1352-03-01:0":{"b": ["Çorum is mentioned in Eretna's country — the city's first known testimony", "bf7bd67f"], "d": ["Çorum is counted among the cities under his rule at the death of Eretna Bey in Muharram 753. The founding of the city is unknown; this mention is the earliest dated testimony that can be found.", "68c8fd3f"]},
"OLAYLAR_SEHIR_ILK:1368-01-20:0":{"b": ["Brăila is first mentioned — the privilege document of Vlaicu Vodă to the merchants of Brașov", "0b3517a7"], "d": ["Vladislav, voivode of Wallachia, gave the merchants of Brașov a document granting them facilities in carrying goods by way of Brăila. This document is the first known written testimony to Brăila; the place appears in it not yet as a city but as the Danube end of the road. It is not the date of foundation.", "8ed7db79"]},
"OLAYLAR_SEHIR_ILK:1420-01-01:0":{"b": ["Chișinău is first mentioned in a decree of the voivode of Moldavia", "a50799d7"], "d": ["The name of Chișinău first appears in a decree of 1420 of the Moldavian voivode Alexandru. The city remained for a long time a small Moldavian town; when it passed to Russia together with Bessarabia in 1812, it became the provincial centre.", "61d831d5"]},
"OLAYLAR_SEHIR_ILK:1445-01-01:0":{"b": ["Galați is first mentioned in a document of a voivode of Moldavia", "a31af8a2"], "d": ["Stephen II, voivode of Moldavia, exempted two carts of Humor Monastery bringing fish from Galați from customs duty. This document is the first definitely known written testimony to Galați; the settlement may earlier have existed as a fishing village on the Danube bank.", "40d464f1"]},
"OLAYLAR_SEHIR_ILK:1452-04-03:0":{"b": ["The name of Mostar first appears in a Dubrovnik document", "a599bc55"], "d": ["The name of Mostar first appears in a Dubrovnik document dated 3 April 1452; the settlement was within the lands of the Duchy of Herzegovina. The Ottoman conquest was in 1466–68.", "5fba613f"]},
"OLAYLAR_SEHIR_ILK:1458-01-01:0":{"b": ["The Hünkâr Mosque at Sarajevo — the earliest dated testimony of the settlement", "ad697a7d"], "d": ["İshak Bey, sancak bey of Bosnia, had a palace built for himself in the first Muslim settlement on the Sarajevo plain, the Hünkâr Mosque in the name of Sultan Mehmed the Conqueror, and a bath beside it. The mosque is dated 862 (1458); it is the earliest dated building of Sarajevo known.", "d7927c3d"]},
"OLAYLAR_SEHIR_ILK:1462-02-01:0":{"b": ["The endowment deed of İshak Bey — the urban core of Sarajevo was endowed", "0b364229"], "d": ["From the endowment deed (vakfiye) of İshak Bey dated Jumada I 866 (February 1462) it is understood that besides the mosque and bath, a zaviye, a Mevlevi lodge, a soup kitchen (imaret), a bridge over the Miljacka, the Kolobara Inn on the opposite bank, a covered market (bedesten), a caravanserai and shops were built. The document is the endowment foundation of the city; the settlement existed before it.", "5f20e8f0"]},
"OLAYLAR_SEHIR_ILK:1472-06-08:0":{"b": ["Tatarpazarcığı is first recorded in an akıncı register", "3b1c839e"], "d": ["The earliest records about the city go back to the year 877 (1472): an akıncı register in the National Library of Sofia records the settlement.", "45a744f9"]},
"OLAYLAR_SEHIR_ILK:1494-02-06:0":{"b": ["Banja Luka is first mentioned in an instruction of King Vladislaus II", "0ebc6288"], "d": ["The name Banja Luka first appears in an instruction of Vladislaus II, king of Hungary and Croatia, dated 6 February 1494; the region was attached to the Hungarian crown through the banate of Jajce. The Ottoman conquest was in the winter of 1527–28.", "02da21ca"]},
"OLAYLAR_SEHIR_ILK:1494-10-02:0":{"b": ["The people of Basra complete their move to the present site — old Basra is abandoned", "20f96eac"], "d": ["The people had gradually begun to settle in present-day Basra, which they found safer against Bedouin attacks and where they could obtain water more easily; the move to the new site was completed in the year 900 (1494–95). Old Basra, founded in the time of Caliph Umar, was about 25 km from the present city.", "7e2ce96c"]},
"OLAYLAR_SEHIR_ILK:1503-01-01:0":{"b": ["Mengli Giray Khan had the Khan's Palace built beside the Çürüksu — the foundation of Bahçesaray", "0792497c"], "d": ["In the valley that was the summer hunting and resting region of the governors of the Golden Horde and of the first Crimean khans, Mengli Giray Khan I had the palace now known as the Khan's Palace built beside the Çürüksu and thus laid the foundation of Bahçesaray. The city developed around the palace and along the narrow Çürüksu valley, flourished at the end of the sixteenth century, and became the centre of the Crimean Khanate.", "dbbc246c"]},
"OLAYLAR_SEHIR_ILK:1552-01-01:0":{"b": ["The Zaporozhian Cossacks founded the first Sich on the island of Khortytsia", "e6ca0dd9"], "d": ["Prince Dmytro Vyshnevetsky founded the first Zaporozhian Sich on the island of Little Khortytsia in the Dnieper. The fortress was besieged and destroyed by the Crimean Tatars in 1558; the Sich later moved to the islands to the south. Term: «Sich» (Ukrainian Sich) is the central camp of the Zaporozhian Cossacks on the Dnieper islands, fortified with logs and ditches; it is the headquarters, the seat of the assembly (Rada) and the centre of the elected head of the host (koshovyi), not a state capital.", "2af408f9"]},
"OLAYLAR_SEHIR_ILK:1593-01-01:0":{"b": ["The Bazavluk Sich was founded", "fcd507ae"], "d": ["After the Tatars destroyed the Tomakivka Sich, the Zaporozhian Cossacks founded a new Sich on the island of Bazavluk, where the Dnieper joins its Chortomlyk, Pidpilna and Skarbna branches. The Sich was destroyed in 1638 by a Polish campaign after the suppression of the Cossack uprising. Term: «Sich» (Ukrainian Sich) is the central camp of the Zaporozhian Cossacks on the Dnieper islands, fortified with logs and ditches; it is the headquarters, the seat of the assembly (Rada) and the centre of the elected head of the host (koshovyi), not a state capital. At this date the 'Hetmanate' does not yet exist (1648); the name Zaporozhia means 'beyond the rapids,' and the Sichs stand on the steppe frontier below the Dnieper rapids. There is no ethnic kinship with the Cossacks of Kazakhstan: the Zaporozhian Cossacks are an East Slavic (Ukrainian), Orthodox community; the only thing in common is the word 'kazak' (free warrior) of Turkic origin.", "ecc27d31"]},
"OLAYLAR_SEHIR_ILK:1628-01-01:0":{"b": ["The Mykytyn Rih Sich is first mentioned", "61e22abc"], "d": ["The name of the fourth Sich, founded at Mykytyn Rih on the site of present-day Nikopol, first appears in 1628; it was captured by Bohdan Khmelnytsky in 1648. This is the first known testimony of the place, not its foundation.", "63f059d0"]},
"OLAYLAR_SEHIR_ILK:1652-01-01:0":{"b": ["The Chortomlyk Sich was founded", "4b6e8197"], "d": ["The Zaporozhian Cossacks founded the Chortomlyk Sich, also called the 'Old Sich,' on the cape where the Dnieper joins the Chortomlyk river. The Sich was destroyed by the Russian army on 25 May 1709 because they had supported Mazepa.", "e7b8c2ca"]},
"OLAYLAR_SEHIR_ILK:1654-01-01:0":{"b": ["Kharkiv was founded by Cossack settlers", "288b303c"], "d": ["On the northern edge of the Wild Steppe, at the confluence of the Lopan and Kharkiv rivers, Cossack settlers who had come from the right bank of the Dnieper founded a settlement. Kharkiv soon became the centre of Sloboda Ukraine, attached to Moscow.", "0d185061"]},
"OLAYLAR_SEHIR_ILK:1711-01-01:0":{"b": ["The Zaporozhian Cossacks founded the Oleshky Sich with the permission of the Crimean khan", "ed26f29d"], "d": ["When the Russian offensive forced the evacuation of the Sich at Kamianka, the Zaporozhian Cossacks settled, with the permission of the Crimean khan, at Oleshky on the left bank of the Konka river on the khanate's lands. After the Treaty of the Prut, Hordiienko's Cossacks joined them. The khan did not allow the Sich to have walls or cannon.", "acb5924a"]},
"OLAYLAR_SEHIR_ILK:1728-01-01:0":{"b": ["The Oleshky Sich was plundered and abandoned", "52361709"], "d": ["The pro-Russian Samara Cossacks raided and plundered the Oleshky Sich and set the barracks on fire. The Sich was not re-established; the Cossacks returned to Kamianka in 1730 and in 1734 swore allegiance to Russia and founded the New Sich.", "bf03f792"]},
"OLAYLAR_SEHIR_ILK:1738-01-01:0":{"b": ["The fortress of Stavropol was founded on the Volga", "eb087a50"], "d": ["On the Middle Volga, the fortress of Stavropol was founded for the Kalmyks who had accepted Christianity (present-day Tolyatti).", "d486bb18"]},
"OLAYLAR_SEHIR_ILK:1738-03-24:0":{"b": ["Nadir Shah takes Kandahar and has the old city destroyed", "9cc23e6b"], "d": ["The Afsharid ruler Nadir Shah took Kandahar, held by the Ghilzai Afghans, after a long siege. The city was destroyed and its people moved to Nadirabad, founded southeast of the old site; old Kandahar never again became a city.", "c8df437b"]},
"OLAYLAR_SEHIR_ILK:1777-01-01:0":{"b": ["The fortress of Stavropol was founded on the Azov–Mozdok line", "7fd9b9f1"], "d": ["On the Azov–Mozdok line of fortifications, founded after Küçük Kaynarca to control the steppe between the Kuban and the Terek, ten fortresses were built; one of them was Stavropol. The fortress later became the centre of the Caucasus governorship and of the governorate of Stavropol.", "f27157a3"]},
"OLAYLAR_SEHIR_ILK:1778-01-01:0":{"b": ["The Kherson shipyard was founded at the mouth of the Dnieper", "115f2c34"], "d": ["At the mouth of the Dnieper, which passed to Russia after Küçük Kaynarca, a shipyard was founded near the fortification of Aleksandr-shants, which had been built in 1737 and soon destroyed, and was given the name Kherson. The city became a district centre in 1784 and a governorate centre in 1803.", "a664a96e"]},
"OLAYLAR_SEHIR_ILK:1779-01-01:0":{"b": ["Greeks from Crimea founded Mariupol on the Azov coast", "4e3af209"], "d": ["Greeks who had come from Crimea founded Mariupol at the place where the Kalmius flows into the Sea of Azov. The city became a district centre within the governorate of Yekaterinoslav in 1784.", "d36ebbc5"]},
"OLAYLAR_SEHIR_ILK:1783-01-01:0":{"b": ["Yekaterinoslav moved to its present site on the Dnieper", "ec361381"], "d": ["Yekaterinoslav, which Potemkin had founded in 1778 at the confluence of the Kilchen and Samara rivers, was moved to its present site in 1783 because of its unhealthy location.", "b37ccddb"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:0":{"b": ["The Russian naval port of Sevastopol was founded in the Akhtiar bay", "01058a25"], "d": ["After the annexation of Crimea to Russia in 1783, the bay where the Crimean Tatar village of Akhtiar (Akyar) stood was chosen for a military port; the port was founded the next year and took the name Sevastopol. In 1804 the city became the main port of the Russian Black Sea fleet.", "03079154"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:1":{"b": ["The fortification of Nikolayev was founded at the mouth of the Bug", "d57e52b9"], "d": ["A fortification was founded on the order of Prince Potemkin at the confluence of the Southern Bug and Ingul rivers. In 1788 a shipyard was opened there, and the settlement became one of the shipbuilding centres of the Black Sea fleet.", "76edde36"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:2":{"b": ["A frontier settlement, the nucleus of Melitopol, was founded on the Molochna", "637d5817"], "d": ["After the annexation of Crimea, a frontier settlement was founded on the bank of the Molochna River. The settlement took the name Novooleksandrivka in 1816 and was made a town under the name Melitopol in 1841.", "9151422f"]},
"OLAYLAR_SEHIR_ILK:1805-01-01:0":{"b": ["Novocherkassk, the new centre of the Don Cossack Host, was founded", "bf5709fd"], "d": ["The administrative centre of the Don Cossack Host passed from Cherkassk, which had been the centre until then, to Novocherkassk, founded at the locality of Biryuchiy Kut between the Aksay and Tuzlov rivers.", "544a425d"]},
"OLAYLAR_SEHIR_ILK:1813-03-06:0":{"b": ["Wadi Halfa is recorded in Burckhardt's journey in Nubia", "6efc72ec"], "d": ["The Swiss traveller J. L. Burckhardt writes in his journal of 6 March 1813 that he passed through Wadi Halfa and that some trade was carried on there. It is the first dated testimony that can be found.", "a3a1877c"]},
"OLAYLAR_SEHIR_ILK:1827-01-01:0":{"b": ["The landing of Berdyansk was founded on the Azov coast", "908ac3cf"], "d": ["At the initiative of Prince Mikhail Vorontsov, Berdyansk was founded at the place where the Berda River flows into the Sea of Azov. The settlement became a town in 1835 and a district centre in 1842.", "8742949e"]},
"OLAYLAR_SEHIR_ILK:1838-01-01:0":{"b": ["The people of Malatya remain in the Aspuzu gardens — the nucleus of modern Malatya", "d1dba159"], "d": ["In the summer of 1838 the Ottoman general headquarters against İbrahim Pasha's Egyptian army moved from Mezraa to Malatya. The people of Malatya, who lived in their summer houses at Aspuzu, did not return after the army's departure to their winter houses in the old city, which had been left in ruins; Aspuzu became the nucleus of modern Malatya. Old Malatya (Battalgazi) continued to live on, reduced in size.", "f4d616ac"]},
"OLAYLAR_SEHIR_ILK:1918-04-02:0":{"b": ["Van is founded on its new site — the ruined old city is abandoned", "6d278578"], "d": ["Van was freed from occupation on 2 April 1918. Those who returned, instead of repairing the old Van on the lake shore that had been ruined in the war years, founded a new city about 7 km inland from the shore on the site of the old Norşen and Arak quarters. The old city was abandoned.", "5a729844"]},
"OLAYLAR_SENKRON_0930:1298-01-01:0":{"b": ["Marash passed to the Mamluks — the governor of Aleppo, Bilban al-Tabakhi, retook it from the Armenians", "03171265"], "d": ["Marash, held since 1258 by the Armenian Kingdom of Cilicia, had passed briefly to the Mamluks in 1293 through Sultan Khalil's treaty with the Armenians, and after their withdrawal had fallen again into Armenian hands. In 697 (1298) Bilban al-Tabakhi, the Mamluk governor of Aleppo, retook the city. Marash thereafter remained Mamluk territory until the rise of the Dulkadirids.", "8fd31b13"]},
"OLAYLAR_SENKRON_0930:1372-01-01:0":{"b": ["The Byzantine Empire became a tributary of the Ottomans", "615df998"], "d": ["After the victory at Chirmen (1371), the Byzantine emperor John V agreed in the winter of 1372 to become a tributary of Murad I: he would pay an annual tribute and furnish troops for the sultan's campaigns. From this date until 1403 Byzantium remained a vassal state dependent on the Ottomans; Bayezid the Thunderbolt's blockade of 1391 increased the tribute. After the Ankara defeat, the Treaty of Gallipoli (1403) with Süleyman Çelebi freed Byzantium from tribute; with the treaty made with Murad II in 1424 the tribute began again.", "e3c816ac"]},
"OLAYLAR_SENKRON_0930:1399-09-01:0":{"b": ["Bayezid the Thunderbolt annexed Besni, Darende and Divriği to Ottoman lands after the death of Barquq", "8e57d7e6"], "d": ["After the death of the Mamluk Sultan Barquq (June 1399), when the administrative affairs of the Mamluk State fell into disorder, Bayezid the Thunderbolt descended on the Euphrates basin and annexed Besni (Behisni), Darende and Divriği, together with Malatya, to Ottoman lands. Sivas had been left to the Ottomans before this, after the death of Qadi Burhan al-Din in the summer of 1398. Divriği had been under Mamluk rule since 1391 and was a forward outpost attached to the province of Aleppo. Ottoman administration did not last long here: because of the approaching danger from Timur, Divriği was given back to the Mamluks in 1401, and the city's definitive entry under Ottoman administration came after Marj Dabiq in 1516.", "ec7cd171"]},
"OLAYLAR_SENKRON_0930:1400-08-01:0":{"b": ["Besni passed to the Mamluks during Timur's Sivas and Malatya campaign", "4853da9a"], "d": ["Besni, which Bayezid the Thunderbolt had taken in 1398 together with Sivas, Darende and Malatya, fell into the hands of the Mamluks in 1400 as Timur took Sivas and Malatya. Timur also took Besni on 27 September 1400 after a fierce siege; when he withdrew from that region Besni came again under Mamluk rule, and remained with the Mamluks (except for a Dulkadirid interlude) until Selim the Grim took it in August 1516.", "0ead96f9"]},
"OLAYLAR_SENKRON_0930:1401-01-01:0":{"b": ["Divriği given back to the Mamluks because of the Timurid danger", "97196b1f"], "d": ["Divriği, which Bayezid the Thunderbolt had taken from the Mamluks in 1398, was left to the Mamluks again in 1401 upon Timur's approach to Anatolia. For this reason, after Timur's destruction of Sivas (1400), Divriği appears on the map in Mamluk colour; in the same months Bayezid was taking Erzincan and Kemah in the east, that is, Mamluk land was left between the Ottoman lands in the west (Sivas) and in the northeast (Kemah). Divriği passed definitively to the Ottomans only after Marj Dabiq in 1516.", "3f13d015"]},
"OLAYLAR_SENKRON_0930:1414-01-01:0":{"b": ["Mamluk Sultan Sheikh retook Antep and Darende from the Dulkadirids", "f90c9508"], "d": ["The Mamluk Sultan Sheikh, worried by the Dulkadirids' friendship with the Ottomans, set out on campaign in 1414; he retook Antep and Darende, which he had earlier given of his own accord to the Dulkadirids.", "9f9b94e1"]},
"OLAYLAR_SENKRON_0930:1418-01-01:0":{"b": ["Dulkadiroğlu Mehmed Bey retook Darende and annexed Besni to his lands", "df914dcb"], "d": ["Dulkadiroğlu Mehmed Bey retook in 1418 Darende, which the Mamluks had taken in 1414, and also annexed Besni to his lands.", "d469f850"]},
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["The Mamluks defeated the Dulkadirids at Antep; Besni returned to Mamluk administration (approximate)", "72742430"], "d": ["The Mamluk army defeated the Dulkadirids at Antep in 1436, and Mehmed Bey withdrew to Akdağ. The year of Besni's return to the Mamluks is not written in the source; Besni had been joined to Dulkadir in 1418, and had returned to the Mamluks before Shahsuvar Bey took it from them in 1465. The atlas gives Besni back to the Mamluks together with this defeat at the neighbouring center of Antep (declared approximation).", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["Dulkadiroğlu Shahsuvar Bey took Besni from the Mamluks (approximate)", "843f0fc4"], "d": ["Shahsuvar Bey (1465-1472), appointed Dulkadir bey by Mehmed the Conqueror, took Besni, Gerger, Birecik and Rumkale, which were in Mamluk hands; the Mamluks were defeated at Turnadağı in the autumn of 1467 and near Antep in the spring of 1468.", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["Emir Yeshbek defeated Shahsuvar Bey; Besni returned to Mamluk administration (approximate)", "4d856aee"], "d": ["In the spring of 1471 Emir Yeshbek defeated Shahsuvar Bey on the Savron stream; the Mamluks retook Kadirli and Kozan. Shahsuvar was executed in Cairo in 1472, and the Mamluks reinstated Shah Budak as bey. With this return, Besni also came under Mamluk administration (TDV besni: 'Toward the end of the fifteenth century it again fell into the hands of the Mamluks').", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["Ferdinand's forces held and fortified Szolnok", "6c8416e6"], "d": ["As the Ottomans were preparing to build a fortress at Szolnok on the Tisza, the forces of Ferdinand I got ahead of them: in mid-September 1550 they occupied Szolnok, and the fortress was made defensible by mid-October. Thus Szolnok, which belonged to Isabella's country, fell into Habsburg hands a year before Transylvania passed to Ferdinand; the Ottomans took the fortress in 1552.", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["Transylvania passed to Habsburg administration: the Kolozsvár diet recognized Isabella's abdication", "8458a566"], "d": ["Following Martinuzzi's agreement with Ferdinand, Queen Isabella, on behalf of the infant king John Sigismund, signed on 19 June 1551 at the fortress of Szászsebes the act of renunciation imposed upon her. The Transylvanian diet, meeting at Kolozsvár on 26 July, recognized this renunciation and the sovereignty of King Ferdinand; the Habsburg army of General Castaldo entered Weissenburg (Gyulafehérvár). Thus Transylvania, dependent on the Ottomans, passed to a Habsburg administration that would last five years.", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["Habsburg administration ended in Transylvania: Transylvania again became a voivodeship dependent on the Ottomans", "721a482a"], "d": ["Because János Zsigmond was a minor, the Habsburgs tried in 1551 to take control of Transylvania by the hand of the Croatian-born priest Martinuzzi (Fráter György), appointed his guardian; Gyulafehérvár, Kolozsvár, Brassó and Segesvár remained under Habsburg administration for five years. The Ottomans prevented this situation, and Transylvania again became a tributary voivodeship dependent on them. Thereafter, in the sixteenth and seventeenth centuries, Transylvania for about 150 years maintained a status based on broad autonomy in internal affairs and dependence on Istanbul in external affairs.", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["Várad, Huszt and Tokaj passed to the Szapolyai side", "587c782d"], "d": ["Following Isabella and János Zsigmond's return to Transylvania in 1556, the supporters of Szapolyai besieged Nagyvárad in 1556. In 1557 the aristocrats of the Upper Tisza took the most important royal fortresses — Várad, Huszt and Tokaj; only Gyula and Világos remained in Ferdinand's hands. Várad thereafter became a fortress of the Principality of Transylvania and remained so until the Ottomans took it in 1660.", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["Schwendi took Szatmár — the northern tip of Transylvania passed to the Habsburgs", "2256bb27"], "d": ["Szatmár, which had passed to the Habsburgs in 1561 when Menyhért Balassa changed sides, had been retaken by a surprise attack by István Báthory in the autumn of 1564 and joined to Transylvania. The Habsburg commander Lazarus von Schwendi launched a counteroffensive in February 1565: Tokaj fell on 9 February, Szerencs four days later, and Szatmár came into the hands of the imperial forces almost without resistance.", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["Bocskai's forces took Szatmár", "e93b098b"], "d": ["As the Bocskai uprising spread to northeastern Hungary, Gyulaffy took Szatmár, which he had besieged, on 21 January 1605. The Peace of Vienna of 23 June 1606 left the county of Szatmár to Bocskai for life; since there was no male heir, the county returned to the crown upon Bocskai's death on 29 December 1606.", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["Death of István Bocskai — the county of Szatmár returned to the crown", "3721bb9b"], "d": ["The prince of Transylvania, István Bocskai, died at Kassa on 29 December 1606. The Peace of Vienna (23 June 1606) had left him the counties, including Szatmár, for life, to return to the crown if there was no male heir; by this provision the county of Szatmár passed back to the Habsburg Hungarian kingdom. Transylvania entered a search for a new prince.", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["Gábor Bethlen took control of the county of Szatmár", "80263da1"], "d": ["With Gábor Bethlen's Hungarian campaign in the autumn of 1619, the county of Szatmár came under the control of the prince of Transylvania; in November 1619 he was addressing the county by letter. The preliminary agreement of 23 January 1620 and the Peace of Nikolsburg left the seven counties, including Szatmár, to Bethlen for life. After Bethlen's death (15 November 1629) the return of the counties to the crown was completed on 30 March 1630.", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["Return of Gábor Bethlen's seven counties to the crown completed", "31b5968f"], "d": ["The Peace of Nikolsburg had left seven Upper Hungarian counties, including Szatmár, to Gábor Bethlen for life. After Bethlen's death on 15 November 1629, the return of the counties to the crown began with the instruction of 30 November 1629 and was completed on 30 March 1630.", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["George I Rákóczi took over Szatmár", "f398635b"], "d": ["In the 1644 campaign of George I Rákóczi, prince of Transylvania, the German garrison of Szatmár entered Rákóczi's service and the fortress fell into Transylvania's hands. The Peace of Linz of 16 December 1645 left the fortress to Rákóczi's heirs for as long as a Rákóczi sat on the throne of Transylvania.", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["Loss of Nitra — De Souches retook the fortress", "c71bf012"], "d": ["Nitra, which had surrendered after brief resistance following the conquest of Uyvar (Érsekújvár) in 1663, was besieged by the imperial commander De Souches on 15 April 1664; the fortress surrendered on 3 May 1664. Since the Treaty of Vasvár left captured places as they stood, Uyvar remained Ottoman while Nitra remained in Habsburg hands.", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["Loss of Léva", "f311920e"], "d": ["After Nitra, De Souches besieged Léva on 9 June 1664; the capitulation was signed on 13 June and the fortress was in the hands of the imperial forces on 14 June. The battle of Léva (Garamszentbenedek) on 19 July 1664 did not change the ownership; it ended with the Habsburgs retaining Léva and Nitra.", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["Doroshenko surrendered Chyhyryn to Samoylovych", "3b538237"], "d": ["Petro Doroshenko, hetman of Right-Bank Ukraine under Ottoman protection, surrendered his capital Chyhyryn on 19 September 1676 to Samoylovych, hetman of the Left Bank, and to Russian forces. The Ottomans removed Doroshenko and installed Yuri Khmelnytsky in his place; the siege of 1677 to drive out the Russian garrison in Chyhyryn failed, and the fortress was taken only on 21 August 1678.", "cccf7b79"]},
"OLAYLAR_SENUSI_0919:1551-07-01:0":{"b": ["The surrender of the Banat fortresses of Transylvania (Temesvár, Lippa, Lugos, Karánsebes) to Ferdinand, King of Hungary", "0e354976"], "d": ["In 1551 the Habsburg army under General Castaldo entered Transylvania; Queen Isabella and her son were forced to renounce their rights to the Hungarian throne. With Castaldo's approval, in mid-July 1551 Martinuzzi sent Endre Báthory to take over the fortresses of Temesvár, Lippa, Solymos, Karánsebes, Lugos, Becse, Becskerek and Csanád in Ferdinand's name. The southern fortresses of Transylvania, which was under Ottoman protection, thus passed into Habsburg hands; Süleyman the Lawgiver's campaigns of 1551–1552 are the response to this.", "420ca62a"]},
"OLAYLAR_SENUSI_0919:1554-04-07:0":{"b": ["The appointment of Péter Petrovics as sancakbeyi of Lugos and Karánsebes", "bcbe73e4"], "d": ["At the insistent request of Isabella and Petrovics, Süleyman the Lawgiver decided to send the young John Sigismund back to Transylvania. In a letter written from Aleppo on 7 April 1554 he ordered the people of Transylvania to take the child back to his country; he also commanded the voivodes of Wallachia and Moldavia to assist Petrovics, whom he appointed at the same time as sancakbeyi of Lugos and Karánsebes. Lugos, conquered in 1552, was thus given to Petrovics as an Ottoman sancak.", "6c5be465"]},
"OLAYLAR_SENUSI_0919:1596-05-10:0":{"b": ["The lifting of the siege of Lippa — the raid of the ban of Lugos on Temesvár", "be03430e"], "d": ["In the spring of 1596 the pasha of Temesvár besieged Lippa. In the night between 10 and 11 May, on the order of György Palatics, ban of Lugos of Transylvania, the soldiers of György Buday raided the suburbs of Temesvár and set them on fire; the fact that György Borbély fired all the cannon in the fortress also convinced the pasha that relief had arrived. On 11 May the pasha withdrew from before Lippa and hurried to protect his own seat. At this time Lugos was in the hands of the Principality of Transylvania.", "07e2cb97"]},
"OLAYLAR_SENUSI_0919:1688-01-01:0":{"b": ["The occupation of Orsova by Austrian forces under Veterani", "1b4a4f6c"], "d": ["In the campaign of 1688, after taking Karánsebes, General Veterani marched on Orsova and occupied it as well. The source gives no day for the occupation; the year base, 1 January 1688, has been used.", "1dfe042e"]},
"OLAYLAR_SENUSI_0919:1689-07-15:0":{"b": ["The recapture of Orsova by Thököly and the Ottoman forces", "c5645da9"], "d": ["After the capture of Vetislan, Thököly and the Ottoman pashas marched on Orsova, which Veterani had occupied in 1688. After insignificant skirmishes, Thököly entered Orsova on 15 July 1689. Heissler, who had come on news of the danger, saw that the force facing him was well equipped with munitions and ships, and withdrew to protect Transylvania. Herbeville's attack before the town in August also failed to retake Orsova.", "6d469bdd"]},
"OLAYLAR_SENUSI_0919:1691-01-01:0":{"b": ["The sancak of Lugos came under Habsburg occupation (1691–1695)", "c8bcd6bd"], "d": ["The sancak of Lugos remained under Habsburg (German) occupation between 1691 and 1695; Mustafa II reconquered it on 22 September 1695. In the old record, 1689–1695 was a declared gap; the 1691–1695 slice is now painted as Habsburg, and 1689–1691 remains a gap. The date has been taken as a year only.", "053d32c8"]},
"OLAYLAR_SENUSI_0919:1716-10-13:0":{"b": ["The fortress of Lugos came under Habsburg administration", "6a9d401f"], "d": ["Lugoj, a sancak fortress belonging to the province of Temeşvar, had been in Ottoman hands since 1695; with the surrender of the provincial centre at the end of the siege of 1716 it was ceded to the Habsburg Monarchy. The old record placed the transfer at the year base, 1 January 1716.", "ab78a026"]},
"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["The capture of Orsova by the Habsburg army (campaign of 1717)", "7a4faffe"], "d": ["In the campaign of 1717, General Splényi arrived before Orsova on 27 August and took the town easily; Orsova, which Mercy had been unable to take in 1716, thus passed into Habsburg hands. Because the surrounding Danube-bank cells (including the Đerdap section on the Serbian side) depend on the nearest settlement point, Orsova, they are painted with its owner. The date has been taken as a year only; the exact day is unconfirmed.", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["The passing of the palanka of Orsova to the Ottomans — the garrison commander's withdrawal to Ada Kale", "de759b16"], "d": ["At the opening of the campaign of 1738, Hacı Mehmed Pasha, the commandant of Vidin, attacked the Erzsébet redoubt on the Danube. On the afternoon of 8 May a sipahi detachment of 4,000–5,000 men marched from the left bank of the Danube to Orsova and attacked the palanka of Orsova; the Austrian commander, after losing about a hundred men, withdrew to New Orsova, that is, to the island fortress of Ada Kale. After the Mehadia engagements in July, Ada Kale too passed into Ottoman hands in August 1738; the Treaty of Belgrade of 1739 recognized the situation.", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["Murad II took Alacahisar; Niš and Şehirköy returned to the Ottomans", "54af926a"], "d": ["After the childless death of the Serbian Despot Stefan Lazarević (1427), Murad II, claiming to be the legitimate heir of Serbia on the basis of Bayezid the Thunderbolt's marriage to a Serbian princess, took action and took Alacahisar (1428). In the same year, after Lazarević's death, the Ottomans also recovered the fortress of Şehirköy — the town had been taken by Stefan in 1412 and defended against Musa Çelebi. According to the TDV article on Niš, the Ottomans retook Niš in the same year as well (831/1428). Thus the line connecting the Great Morava and Nišava valleys came under Ottoman control.", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["The Crusader army captured Şehirköy — the Nišava branch of the 'Long Campaign'", "fdf6140c"], "d": ["The Crusader army under King Vladislav and the Serbian Despot Đurađ Branković captured Şehirköy in 1443. In the continuation of the same campaign, the Ottoman forces would be routed in November at the Zlatica pass. After the Treaty of Szeged (1444), Şehirköy was given back to the Serbs by Murad II, but it passed to the Ottomans after the death of Đurađ Branković in 1456.", "f56645a4"]},
"OLAYLAR_SERHAT:1458-01-01:0":{"b": ["Definitive Ottoman rule was established in the Alacahisar region", "9715382a"], "d": ["Alacahisar, left to Branković under the treaty made with the Hungarian delegates in 1444, came under Turkish rule again in the years following the victory at Varna. This second conquest of the city is documented not by a record of war but by a fiscal record: the timar registers of some villages dependent on Alacahisar are dated to the end of 1453/beginning of 1454; but this is only village testimony — in 1454 the Ottoman forces were defeated near Alacahisar, and in 1455 Alacahisar was left to Branković as a border. According to the TDV, definitive Ottoman rule in the region was established in 1458.", "2b6aba24"]},
"OLAYLAR_SESSIZBORC0919:1349-01-01:0":{"b": ["The founding of the Despotate of the Morea — Manuel Kantakouzenos at Mistra", "87660b82"], "d": ["The Byzantine emperor John Kantakouzenos gave his son Manuel a separate administrative region in the Morea; thus the Despotate of the Morea, centred on Mistra, came into being. Manuel ruled until 1380; during this period Byzantine culture and art flourished especially at Mistra. The despotate lasted until Mehmed II's conquest in 1460.", "f5596d5e"]},
"OLAYLAR_SESSIZBORC0919:1430-01-01:0":{"b": ["The despot Constantine took Patras from the Franks", "cb0dd18c"], "d": ["Constantine, Despot of the Morea (the last Byzantine emperor in 1449), recovered Patras from the Latins; thus this important port in the northwest of the peninsula was also joined to the despotate. Patras came under Ottoman rule in 1458 in Mehmed II's Morea campaign.", "98b8dff0"]},
"OLAYLAR_SESSIZBORC0919:1448-01-01:0":{"b": ["Stjepan Vukčić Kosača 'Duke of St Sava' — the birth of Herzegovina", "cc67061f"], "d": ["Stjepan Vukčić Kosača, who had united Hum and Trebinje in a single principality, rose against the king of Bosnia and proclaimed himself 'Herzog (duke) of St Sava'; the Emperor Frederick III granted the title in 1448. The name Herzegovina ('the land of the Herzog') comes from this title. Herzegovina passed piece by piece to the Ottomans from 1466, became a sancak in 1470, and its remaining lands were annexed at the beginning of 1482.", "e6a77d9c"]},
"OLAYLAR_SESSIZBORC0919:1525-04-08:0":{"b": ["The Peace of Kraków — the Teutonic Order state became the Duchy of Prussia", "78666ddd"], "d": ["Albrecht of Brandenburg, Grand Master of the Teutonic Knights, signed the Peace of Kraków when he could find no help against Poland. The order state (Ordensstaat) became a hereditary and secular duchy, under Polish suzerainty, passing to the Brandenburg dynasty. The centre was Königsberg; in 1544 Albrecht founded the Albertina University there. The duchy became the Kingdom of Prussia in 1701.", "d38ad9a3"]},
"OLAYLAR_SESSIZBORC0919:1918-11-12:0":{"b": ["Proclamation of the Republic of Austria — the end of the Habsburg monarchy", "c84f316c"], "d": ["On the day after Emperor Karl I withdrew from affairs of state on 11 November, the Provisional National Assembly adopted the law on the form of state and government, and the republic was proclaimed. The First Republic, centred on Vienna, replaced Habsburg Austria.", "f747ce09"]},
"OLAYLAR_T5_1000A:1008-01-01:0":{"b": ["Batumi under the rule of the Kingdom/Kingdoms of Georgia — a dated attestation in the source", "62cd2833"], "d": ["The source shows the city of Batumi under the administration of the Kingdom/Kingdoms of Georgia at this date; earlier ownership is not dated in the source (the atlas leaves the period before this date blank).", "e03655c9"]},
"OLAYLAR_T5_1000A:1024-01-01:0":{"b": ["The Marwanid Nasr al-Dawla added Amid to his emirate", "9fbc8c85"], "d": ["The Marwanid emir Nasr al-Dawla Ahmad added Amid (Diyarbekir) to the lands of the emirate; the following year he also took Edessa.", "d585a28b"]},
"OLAYLAR_T5_1000A:1054-01-01:0":{"b": ["Maragha came under Seljuk rule", "c011cac9"], "d": ["Maragha, held by the Rawwadids, came under Seljuk rule through Tughril Beg's Azerbaijan campaign.", "2ff74d2d"]},
"OLAYLAR_T5_1000A:1055-12-18:0":{"b": ["Tughril Beg entered Baghdad", "38af55c2"], "d": ["Tughril Beg, who came to Baghdad at the invitation of the caliph al-Qāʾim bi-Amr Allāh, put an end to Buyid rule.", "f7f905d1"]},
"OLAYLAR_T5_1000A:1056-01-01:0":{"b": ["Mosul passed into the hands of the Seljuks", "20b8da93"], "d": ["Mosul passed to the Seljuks together with Iraq; despite al-Basāsīrī's brief occupation, it remained in Seljuk hands for four years.", "a55cff1d"]},
"OLAYLAR_T5_1000A:1061-01-01:0":{"b": ["Mosul again with the Uqaylids", "8b7c0603"], "d": ["In 1061 Mosul again came under Uqaylid rule; even after the Seljuk seizure of 1084, Malik-Shah returned the city to the Uqaylid emir.", "71824a2b"]},
"OLAYLAR_T5_1000A:1064-01-01:0":{"b": ["Alp Arslan ended the shahdom of Nakhchivan", "5620360e"], "d": ["Alp Arslan, who defeated the Rawwadids, abolished the shahdom of Nakhchivan founded by the Dulafids.", "f9fd7d73"]},
"OLAYLAR_T5_1000A:1071-01-01:0":{"b": ["Emir Saltuk conquered Erzurum", "f52c09dd"], "d": ["After Manzikert, Alp Arslan granted the Erzurum region as an iqta to Emir Saltuk; Saltuk took the city in the same year and the Saltukid Beylik was founded (1080 according to Yinanç).", "505fcc25"]},
"OLAYLAR_T5_1000A:1071-01-01:1":{"b": ["Danishmend Gazi conquered Sivas", "348d7ad3"], "d": ["Danishmend Gazi, who took Sivas, which had been granted to him as an iqta after Manzikert, founded the core of the dynasty there (the date of the conquest is disputed; there is also a tradition of 1080).", "b9b5dd65"]},
"OLAYLAR_T5_1000A:1074-01-01:0":{"b": ["Philaretos seized Malatya", "9c80e3bd"], "d": ["Philaretos, who founded an Armenian principality in Cilicia, took Malatya while posing as a Byzantine representative and governed it through governors (Gabriel and others).", "958ede64"]},
"OLAYLAR_T5_1000A:1074-01-01:1":{"b": ["Emir Danishmend conquered Tokat", "c9321fb6"], "d": ["Following the Manzikert victory, Emir Danishmend took Tokat from Byzantium.", "dcc7f8e2"]},
"OLAYLAR_T5_1000A:1085-01-01:0":{"b": ["The Seljuks took Hasankeyf from the Marwanids", "4fa9d559"], "d": ["In the time of Malik-Shah the Seljuks put an end to Marwanid rule and also took Hasankeyf.", "b9794646"]},
"OLAYLAR_T5_1000A:1085-05-31:0":{"b": ["Fakhr al-Dawla's son took Amid, Marwanid rule ended", "ecaf6b03"], "d": ["Za'im al-Ru'asa, the son of Fakhr al-Dawla Ibn Jahir, who had been commissioned by Malik-Shah, took Amid from the Marwanids.", "8745ce9d"]},
"OLAYLAR_T5_1000A:1093-01-01:0":{"b": ["Tutush seized Diyarbekir", "469b8ebc"], "d": ["After Malik-Shah's death, Tutush, who was claiming the sultanate, took the Diyarbekir region and took the last Marwanid emir, Mansur, prisoner.", "52daa285"]},
"OLAYLAR_T5_1000A:1095-01-01:0":{"b": ["The Turkmen bey Sadr began to rule in Amid", "3d67b786"], "d": ["After Tutush's death the Turkmen bey Sadr became master of Amid; his successor İnal founded the dynasty of the İnaloğulları.", "5fdca35c"]},
"OLAYLAR_T5_1000A:1096-01-01:0":{"b": ["Kerbogha seized Mosul", "462a238f"], "d": ["The Seljuk emir Kerbogha took Mosul from the Uqaylids. (Dhu'l-Qa'da 489 / November 1096; in conformity with the register entry (künye), the atlas writes it at year precision.)", "14d9ca6d"]},
"OLAYLAR_T5_1000A:1100-01-01:0":{"b": ["Niksar under Danishmendid rule — a dated attestation in the source", "81181870"], "d": ["The source shows the city of Niksar under the administration of the Danishmendids at this date; earlier ownership is not dated in the source (the atlas leaves the period before this date blank).", "c1463e88"]},
"OLAYLAR_T5_1000A:1102-09-18:0":{"b": ["The Danishmendid Gümüştegin Gazi took Malatya", "87f1166c"], "d": ["Gümüştegin Gazi captured Malatya at the end of a siege.", "2d0e9668"]},
"OLAYLAR_T5_1000A:1106-09-02:0":{"b": ["Kılıcarslan I took possession of Malatya", "eca366d5"], "d": ["After Gümüştegin's death, Kılıcarslan I joined Malatya to Seljuk lands after a siege of more than two months.", "69bdbc2c"]},
"OLAYLAR_T5_1000A:1108-03-04:0":{"b": ["The Mazyadid Sadaqa died at al-Nuʿmāniyya, Hilla passed to the Seljuks", "e5ecea7c"], "d": ["Muhammad Tapar defeated Sadaqa; his son Dubays was taken prisoner and was not permitted to return to Hilla.", "be1e2910"]},
"OLAYLAR_T5_1000A:1111-01-01:0":{"b": ["İlarslan retook Elbistan from Tancred", "923962c2"], "d": ["Elbistan, which Tancred, Prince of Antioch, had taken, was retaken by İlarslan, the atabeg of Tuğrul Arslan, the malik of Malatya.", "ce0754bd"]},
"OLAYLAR_T5_1000A:1112-01-01:0":{"b": ["The Artuqid Belek became master of Harput", "83425a6e"], "d": ["Belek b. Behrâm, a grandson of Artuk Bey, became master of Harput and founded his beylik centred on Palu.", "ff838897"]},
"OLAYLAR_T5_1000A:1116-01-01:0":{"b": ["Niğde under the rule of the Anatolian (Turkey) Seljuk State — a dated attestation in the source", "dfb24c4b"], "d": ["The source shows the city of Niğde under the administration of the Anatolian (Turkey) Seljuk State at this date; earlier ownership is not dated in the source (the atlas leaves the period before this date blank).", "477146f3"]},
"OLAYLAR_T5_1000A:1117-01-01:0":{"b": ["Dubays returned to Hilla", "9bc0e03a"], "d": ["After Muhammad Tapar's death, Dubays was able to go to Hilla in the time of the Iraqi Seljuk sultan Mahmud.", "d9aec87c"]},
"OLAYLAR_T5_1000A:1118-05-06:0":{"b": ["Mahmud was proclaimed Iraqi Seljuk sultan in Baghdad — the Iraqi Seljuk State was founded", "18babf94"], "d": ["After Muhammad Tapar's death, his son Mahmud was proclaimed sultan by the caliph; the Iraqi Seljuk State was founded. Baghdad, Mosul and Tikrit remained attached to the Iraqi Seljuk sultanate, and Azerbaijan (Maragha, Nakhchivan) also fell to the Iraqi Seljuk share. In the source, Tikrit appears this year as the iqta of the shihna of Baghdad.", "cf36af86"]},
"OLAYLAR_T5_1000A:1119-01-01:0":{"b": ["John II Komnenos retook Denizli", "cb523c0f"], "d": ["The Byzantine emperor John II Komnenos forced the Seljuk commander in Laodicea, Alp Kara, to withdraw; the lands of Denizli passed to Byzantium again (the Byzantine entry says 1120).", "8bdb49b8"]},
"OLAYLAR_T5_1000A:1120-01-01:0":{"b": ["Aqsunqur al-Ahmadīlī was sent to Maragha", "7a3d6deb"], "d": ["Sultan Mahmud sent Aqsunqur al-Ahmadīlī to Maragha; the Ahmadili atabegate established itself in the city.", "3616b62c"]},
"OLAYLAR_T5_1000A:1124-01-01:0":{"b": ["The Danishmendid Emir Gazi took possession of Malatya; Elbistan also passed to the Danishmendids", "97f3f958"], "d": ["After Belek's death, Emir Gazi took Malatya from the Seljuk malik Tuğrul Arslan after a long siege; with the seizure of the Malatya region, Elbistan also came under Danishmendid administration.", "ae95651d"]},
"OLAYLAR_T5_1000A:1127-01-01:0":{"b": ["Emir Gazi took Ankara from the Seljuks", "25b745cd"], "d": ["The Danishmendid Emir Gazi defeated Malik Arab, the son of Kılıcarslan I, and took Ankara from him.", "008f5e3f"]},
"OLAYLAR_T5_1000A:1127-01-01:1":{"b": ["ʿImād al-Dīn Zengī atabeg of Mosul (Zengids)", "ba79276b"], "d": ["The Iraqi Seljuk sultan Mahmud granted Mosul as an iqta to ʿImād al-Dīn Zengī; the Atabegate of Mosul was founded.", "a1929772"]},
"OLAYLAR_T5_1000A:1134-01-01:0":{"b": ["Kayseri under Danishmendid rule — a dated attestation in the source", "3b9b8604"], "d": ["The source shows the city of Kayseri under the administration of the Danishmendids at this date; earlier ownership is not dated in the source (the atlas leaves the period before this date blank).", "e82b707e"]},
"OLAYLAR_T5_1000A:1142-01-01:0":{"b": ["Kemah under Mengujekid (Mengücekoğulları) rule — a dated attestation in the source", "d86927c6"], "d": ["The source shows the city of Kemah under the administration of the Mengujekids (Mengücekoğulları) at this date; earlier ownership is not dated in the source (the atlas leaves the period before this date blank).", "fcb6186c"]},
"OLAYLAR_T5_1000A:1144-01-01:0":{"b": ["Sultan Mesud took Elbistan", "825e2c56"], "d": ["Mesud I seized Elbistan and Ceyhan from ʿAyn al-Dawla and appointed his son Kılıcarslan as malik.", "d69cdacb"]},
"OLAYLAR_T5_1000A:1148-01-01:0":{"b": ["Nakhchivan joined the Ildegizids", "774400cc"], "d": ["With the dissolution of the Seljuks, Nakhchivan joined the State of the Ildegizids and was their centre until 1174 (the year of joining is unspecified; the beginning of the dynasty).", "bf42d3bd"]},
"OLAYLAR_T5_1000A:1149-01-01:0":{"b": ["Tikrit passed to the Begtegînids (EI2)", "a2caf5af"], "d": ["According to what TDV reports from EI2, Tikrit was under the rule of the Begtegînids between 1149 and 1190.", "d10d23e8"]},
"OLAYLAR_T5_1000A:1150-01-01:0":{"b": ["Sultan Mesud gave Hilla to Sâlârkerd", "4bdbd034"], "d": ["After the death of the Mazyadid Ali, Sultan Mesud gave Hilla to his commander Sâlârkerd.", "059e9aeb"]},
"OLAYLAR_T5_1000A:1152-01-01:0":{"b": ["Sultan Mesud died; Caliph al-Muqtafī became sole master in Iraq, took Hilla, Kufa and Wasit", "21192405"], "d": ["With the death of Sultan Mesud, Caliph al-Muqtafī li-Amr Allāh established rule independent of Seljuk influence in Baghdad and Iraq; the caliph's vizier seized Hilla, and Kufa and Wasit were also taken.", "cd348b82"]},
"OLAYLAR_T5_1000A:1156-01-01:0":{"b": ["Yağıbasan seized Elbistan", "824708d3"], "d": ["After Mesud's death, Yağıbasan, the Danishmendid malik of Sivas, took Elbistan; its administration was left to him by agreement.", "d413e508"]},
"OLAYLAR_T5_1000A:1156-01-01:1":{"b": ["Seljuk commanders took Hilla, the Mazyadids became subject to the deputy", "43afd955"], "d": ["Hilla was taken by the commanders of Sultan Muhammad b. Mahmūd; the Mazyadids ruled as subjects of the sultan's deputy.", "c6c81147"]},
"OLAYLAR_T5_1000A:1160-01-01:0":{"b": ["Baku under the rule of the Shirvanshahs — a dated attestation in the source", "1f2863e4"], "d": ["The source shows the city of Baku under the administration of the Shirvanshahs at this date; earlier ownership is not dated in the source (the atlas leaves the period before this date blank).", "506dae86"]},
"OLAYLAR_T5_1000A:1163-01-01:0":{"b": ["Caliph al-Mustanjid took Hilla, the Mazyadids came to an end", "4348923c"], "d": ["The forces of Caliph al-Mustanjid and of the Banū Muntafiq occupied Hilla, and the Mazyadids were dispersed.", "da071466"]},
"OLAYLAR_T5_1000A:1165-01-01:0":{"b": ["Kılıcarslan II took Elbistan and Darende", "7c109007"], "d": ["Taking advantage of the disputes among the Danishmendids, Kılıcarslan II seized the Elbistan, Darende and Gedük region.", "d258bac6"]},
"OLAYLAR_T5_1000A:1172-01-01:0":{"b": ["The Rubenid Mleh took Tarsus from Byzantium", "2f98fd11"], "d": ["With the help of Nūr al-Dīn Zengī, the Rubenid Mleh retook Adana, Misis and Tarsus from the Byzantines.", "e1cfa006"]},
"OLAYLAR_T5_1000A:1174-01-01:0":{"b": ["The Ildegizid Pehlivan took Tabriz", "f0831f17"], "d": ["The Ildegizid Pehlivan took Tabriz from the Ahmadilis by peaceful means and gave it to his brother Kızılarslan.", "81ee8ab8"]},
"OLAYLAR_T5_1000A:1175-01-01:0":{"b": ["Kılıcarslan II took Sivas and Niksar from the Danishmendids", "584575bb"], "d": ["After the death of Nūr al-Dīn Zengī, Kılıcarslan II seized Sivas, Niksar, Tokat and the other Danishmendid lands in the summer of 1175; the Sivas branch came to an end.", "c8092aea"]},
"OLAYLAR_T5_1000A:1178-10-25:0":{"b": ["Kılıcarslan II took Malatya, the Danishmendid branch ended", "3bdbb060"], "d": ["After a four-month siege Malatya passed to the Seljuks and the Malatya branch of the Danishmendids came to an end.", "b92d6ebb"]},
"OLAYLAR_T5_1000A:1183-04-29:0":{"b": ["Saladin took Amid and gave it to the Artuqid Nūr al-Dīn Muhammad", "8c3cc7bb"], "d": ["Saladin the Ayyubid besieged and took Amid and gave it to the Artuqid emir of Hasankeyf, Nūr al-Dīn Muhammad; the İnaloğulları came to an end.", "b16cdda4"]},
"OLAYLAR_T5_1000A:1184-01-01:0":{"b": ["Rupen III retook Adana from the Crusaders", "e9876f85"], "d": ["Rupen III of the Rubenids retook in 1184 Misis, Adana and Tel Hamdun, which had passed to the Crusaders for a time after Mleh.", "177b5432"]},
"OLAYLAR_T5_1000A:1190-01-01:0":{"b": ["Tikrit passed to the Abbasids", "e8f5aeac"], "d": ["After Begtegînid rule, the city passed under the administration of the Abbasid caliphate.", "f91cfb0d"]},
"OLAYLAR_T5_1000A:1194-01-01:0":{"b": ["Rukn al-Dīn Süleyman Shah II retook Samsun", "0971ebcd"], "d": ["Samsun and the eastern Black Sea lands, which had passed to the Komnenoi during the fratricidal quarrels, were retaken by Süleyman Shah.", "940e4b5b"]},
"OLAYLAR_T5_1000A:1199-01-06:0":{"b": ["Adana and Tarsus: the Rubenid principality became the Armenian Kingdom of Cilicia", "de3c4beb"], "d": ["The Rubenid dynasty, which held Adana and Tarsus, took the title of kingdom; this is a change of title of the same dynasty, and no territory changed hands. The coronation day was NOT FOUND in TDV — the date was taken over from the start of the register entry (künye) of the Armenian Kingdom of Cilicia (the künye date is not a source).", "be8faf2b"]},
"OLAYLAR_T5_1000A:1204-01-01:0":{"b": ["The Empire of Trebizond was founded — Giresun and Sinop also within its borders", "a99b6ba0"], "d": ["Alexios Komnenos, who fled to Trebizond upon the capture of Constantinople by the Latins, proclaimed himself emperor; the city became the centre of the new state. The state founded by the Komnenian grandsons Alexios and David extended as far as Sinop; Giresun also remained within the borders of the Empire of Trebizond.", "dd95df25"]},
"OLAYLAR_T5_1000A:1204-04-13:0":{"b": ["Kütahya under the rule of the Empire of Nicaea (Laskaris) — a dated attestation in the source", "d91fa405"], "d": ["The source shows the city of Kütahya under the administration of the Empire of Nicaea (Laskaris) at this date; earlier ownership is not dated in the source (the atlas leaves the period before this date blank).", "50f100b1"]},
"OLAYLAR_T5_1000A:1205-01-01:0":{"b": ["The Ildegizid Abu Bakr took Maragha", "03faed10"], "d": ["The Ahmadili ʿAlāʾ al-Dīn Körpearslan was obliged to leave the fortress of Maragha to the Ildegizid Atabeg Abu Bakr.", "742aae78"]},
"OLAYLAR_T5_1000A:1206-01-01:0":{"b": ["The Seljuks conquered Denizli and Honaz", "1053ccc8"], "d": ["In the second reign of Ghiyāth al-Dīn Keyhusrev I, Denizli and Honaz passed to the Seljuks (the Byzantine sources say 1196, the Seljuks entry says 603/1207).", "c102dae3"]},
"OLAYLAR_T5_1000A:1208-01-01:0":{"b": ["Ghiyāth al-Dīn Keyhusrev I joined Maraş to the Seljuks again", "91b1544e"], "d": ["Keyhusrev mounted a campaign against the Armenians and joined Maraş to Seljuk lands.", "5ffaa2f3"]},
"OLAYLAR_T5_1000A:1211-01-01:0":{"b": ["Kastamonu under the rule of the Çobanoğulları — a dated attestation in the source", "10b682ba"], "d": ["The source shows the city of Kastamonu under the administration of the Çobanoğulları at this date; earlier ownership is not dated in the source (the atlas leaves the period before this date blank).", "1cdb9e90"]},
"OLAYLAR_T5_1000A:1214-11-02:0":{"b": ["ʿIzz al-Dīn Keykāvus I conquered Sinop", "463ea2b9"], "d": ["The Seljuk sultan ʿIzz al-Dīn Keykāvus I took Sinop from the Komnenoi of Trebizond.", "0a71d5c6"]},
"OLAYLAR_T5_1000A:1222-01-01:0":{"b": ["ʿAlāʾ al-Dīn Keykubad I took Kalonoros (Alaiye)", "5a4d6ac2"], "d": ["The fortress of Kalonoros, east of Antalya, was taken by the Seljuks and, rebuilt, received the name Alaiye (the Alanya entry says 1221).", "a00756da"]},
"OLAYLAR_T5_1000A:1225-01-01:0":{"b": ["Jalāl al-Dīn Khwarazmshah annexed Azerbaijan", "5b812b99"], "d": ["Jalāl al-Dīn Khwarazmshah added Azerbaijan and Arran to his lands (regional sentence).", "5bba4780"]},
"OLAYLAR_T5_1000A:1225-07-01:0":{"b": ["Jalāl al-Dīn Khwarazmshah took Maragha", "a55ec004"], "d": ["Jalāl al-Dīn Khwarazmshah seized Maragha and made it his military and administrative centre in Azerbaijan.", "2aa8a852"]},
"OLAYLAR_T5_1000A:1225-07-25:0":{"b": ["Jalāl al-Dīn Khwarazmshah entered Tabriz", "72904097"], "d": ["When Atabeg Özbek withdrew to Ganja, Jalāl al-Dīn Khwarazmshah entered Tabriz, became master of the city and made it his centre.", "43ee9867"]},
"OLAYLAR_T5_1000A:1228-01-01:0":{"b": ["ʿAlāʾ al-Dīn Keykubad took Kemah", "8c5aa655"], "d": ["The Kemah-Erzincan branch of the Mengujekids was joined to Seljuk lands by ʿAlāʾ al-Dīn Keykubad I, who besieged and took Kemah.", "7edb7223"]},
"OLAYLAR_T5_1000A:1231-01-01:0":{"b": ["Maragha was seized by the Mongols for the second time", "f1320e5d"], "d": ["At the end of Khwarazmshah rule Maragha fell into the hands of the Mongols.", "9cee2a89"]},
"OLAYLAR_T5_1000A:1231-01-01:1":{"b": ["Azerbaijan came under Mongol rule — Tabriz suffered the Mongol occupation", "3f38ef66"], "d": ["With the collapse of Jalāl al-Dīn Khwarazmshah, Tabriz suffered the Mongol occupation in 1231; in the same year Mongol rule covered Northern and Southern Azerbaijan (regional sentence, not specific to the city). In Shirvan (Baku, Shamakhi) the Shirvanshahs continued to exist as a local dynasty under Mongol sovereignty; by Emre's decision the atlas keeps these two points in the Shirvanshah colour (Mongol/Ilkhanid subordination in the note).", "46225c2e"]},
"OLAYLAR_T5_1000A:1232-10-01:0":{"b": ["The Ayyubid al-Malik al-Kāmil took Amid", "9cebe681"], "d": ["Al-Malik al-Kāmil besieged Amid and took it from the Artuqids.", "02085ee1"]},
"OLAYLAR_T5_1000A:1233-01-01:0":{"b": ["ʿAlāʾ al-Dīn Keykubad I took Kütahya from the Empire of Nicaea", "e0b9a7f7"], "d": ["Kütahya, which had passed to Byzantium again in the disorders after 1182, was retaken from the Empire of Nicaea in the time of ʿAlāʾ al-Dīn Keykubad I.", "90db8b27"]},
"OLAYLAR_T5_1000A:1233-01-01:1":{"b": ["Badr al-Dīn Luʾluʾ sultan of Mosul", "73268628"], "d": ["With the death of the last Zengid atabeg, Badr al-Dīn Luʾluʾ was proclaimed sultan by the caliph. (Rabīʿ al-awwal 631 / December 1233; in conformity with the register entry (künye), the atlas writes it at year precision.)", "076b23b0"]},
"OLAYLAR_T5_1000A:1234-08-01:0":{"b": ["The Seljuks took Harput", "3b9391eb"], "d": ["The army of ʿAlāʾ al-Dīn Keykubad took the fortress of Harput after a siege of twenty-four days; the Harput Artuqids came to an end.", "1ae6c0d9"]},
"OLAYLAR_T5_1000A:1240-01-01:0":{"b": ["Ghiyāth al-Dīn Keyhusrev II seized Amid", "c37c3b04"], "d": ["The Anatolian Seljuk sultan Ghiyāth al-Dīn Keyhusrev II took Amid from the Ayyubids.", "f8a0cc8c"]},
"OLAYLAR_T5_1000A:1253-01-01:0":{"b": ["Möngke Qaghan appointed Iftikhār al-Dīn governor of Qazvin", "fc650d13"], "d": ["Möngke, the Great Khan of the Mongols, appointed a governor to Qazvin; the period of the Iftikhārids began.", "c042dadd"]},
"OLAYLAR_T5_1000A:1256-01-01:0":{"b": ["Hülegü's arrival: Qazvin and Nakhchivan passed to Ilkhanid administration", "24673608"], "d": ["With Hülegü's arrival in Iran, Mongol administration passed to the Ilkhanid State; Qazvin and Nakhchivan passed to Ilkhanid administration (rule 5 limit, not the source date). In Shirvan (Baku, Shamakhi) the Mongol occupation brought heavy destruction, but the Shirvanshahs continued as a local dynasty; the atlas keeps these two points in the Shirvanshah colour (Emre's decision).", "14d75e4f"]},
"OLAYLAR_T5_1000A:1257-01-01:0":{"b": ["The Mongols occupied Tikrit", "60af2df0"], "d": ["During the Mongol invasion Tikrit was occupied and plundered; the city passed out of Abbasid administration.", "1a51fdd7"]},
"OLAYLAR_T5_1000A:1257-03-27:0":{"b": ["Hülegü marched from Hamadan to Baghdad", "5f0c77b5"], "d": ["Hülegü set out on the Baghdad campaign from Hamadan, where his baggage was (witness of Ilkhanid rule).", "303cbae8"]},
"OLAYLAR_T5_1000A:1258-01-01:0":{"b": ["Buqa Temür took Kufa and Basra", "dec82b4e"], "d": ["The Mongol forces under Buqa Temür seized Kufa, Wasit and Basra.", "10fd1496"]},
"OLAYLAR_T5_1000A:1258-01-01:1":{"b": ["Iraq passed into the hands of the Mongols (regional)", "7b990281"], "d": ["With Hülegü's occupation of Baghdad in 1258 the Abbasid State was destroyed and Iraq passed into the hands of the Mongols.", "6f12d882"]},
"OLAYLAR_T5_1000A:1258-01-01:2":{"b": ["Maraş was left to the Armenians", "6161f1a5"], "d": ["ʿImād al-Dīn of the family of Ḥusām al-Dīn, finding no support, abandoned Maraş to the Armenians of Cilicia.", "9ea1e7ff"]},
"OLAYLAR_T5_1000A:1258-01-01:3":{"b": ["Wasit passed to Ilkhanid rule", "fbdf83fc"], "d": ["With the Ilkhanids' seizure of Iraq, Wasit came under their administration.", "5f4aee6b"]},
"OLAYLAR_T5_1000A:1258-02-10:0":{"b": ["The Mongols took Baghdad; the end of the Abbasid caliphate", "41c34bd4"], "d": ["The Mongols under Hülegü's command attacked Baghdad and Caliph al-Mustaʿṣim surrendered; the city passed to Ilkhanid rule.", "1c979d91"]},
"OLAYLAR_T5_1000A:1262-01-01:0":{"b": ["The Mongols took Mosul, the Luʾluʾid dynasty came to an end", "035d0121"], "d": ["Mosul of al-Malik al-Ṣāliḥ Ismāʿīl, who had sided with Baybars, suffered Mongol destruction, and he himself was killed in Hülegü's presence.", "69cc41a9"]},
"OLAYLAR_T5_1000B:1070-01-01:0":{"b": ["The Friday sermon in Mecca was changed from the Fatimids to the name of the Abbasid caliph and Sultan Alp Arslan", "df951887"], "d": ["When provisions did not arrive because of the famine in Egypt, the emir of Mecca, Abū Hāshim Muhammad b. Jaʿfar, had the khutba read in the name of the Abbasid Caliph al-Qāʾim bi-Amr Allāh and the Seljuk Sultan Alp Arslan; Mecca passed to Great Seljuk suzerainty.", "c8a5b1f7"]},
"OLAYLAR_T5_1000B:1075-01-01:0":{"b": ["Atsız b. Uvak took Damascus", "8eea047f"], "d": ["Atsız seized Syria and had the khutba read in the name of the Abbasid caliph and Malik-Shah.", "1de51f0c"]},
"OLAYLAR_T5_1000B:1076-01-01:0":{"b": ["The emir of Mecca, Abū Hāshim, again had the khutba read in the name of the Fatimid caliph", "85b6c0c0"], "d": ["Despite Malik-Shah's efforts to consolidate Sunni influence, the emir of Mecca began again to have the khutba read in the name of the Fatimids; Mecca returned to Fatimid suzerainty.", "a7ec64c5"]},
"OLAYLAR_T5_1000B:1079-01-01:0":{"b": ["Tutush entered Damascus, the Seljuks of Syria were founded", "b48b38be"], "d": ["Tutush entered the city and founded the Seljuk State of Syria.", "6404e098"]},
"OLAYLAR_T5_1000B:1080-01-01:0":{"b": ["The emir of Mecca declared allegiance to the Abbasid caliph al-Muqtadī and Sultan Malik-Shah", "38a430a5"], "d": ["The emir of Mecca again became subject to the Abbasid caliph and the Seljuk sultan; this allegiance lasted until Malik-Shah's death (1092).", "41ad14e9"]},
"OLAYLAR_T5_1000B:1092-01-01:0":{"b": ["On the death of Sultan Malik-Shah the khutba in Mecca returned to the Fatimids", "195a27cd"], "d": ["When the Seljuk Sultan Malik-Shah died, the emir of Mecca again began to have the khutbas read in the name of the Fatimid caliph; Mecca passed to Fatimid suzerainty.", "00e9a74b"]},
"OLAYLAR_T5_1000B:1097-07-01:0":{"b": ["After the defeat at Dorylaeum, Eskişehir returned to Byzantium", "3f381ee4"], "d": ["Following Kılıcarslan I's withdrawal before the Crusaders, the city again came under Byzantine administration.", "f3155b07"]},
"OLAYLAR_T5_1000B:1104-06-06:0":{"b": ["Toghtekin founded the Atabegate of Damascus", "f26729c0"], "d": ["After Duqaq's death, the atabeg Toghtekin founded the dynasty of the Burids.", "ac9e7419"]},
"OLAYLAR_T5_1000B:1150-01-01:0":{"b": ["The Almohads took Meknes", "ee976b41"], "d": ["After long resistance the city came under Almohad rule and was plundered.", "4924b727"]},
"OLAYLAR_T5_1000B:1154-04-25:0":{"b": ["Nūr al-Dīn Zengī took Damascus", "a4fd8b58"], "d": ["Nūr al-Dīn Mahmud brought Damascus under his rule.", "f87fe7de"]},
"OLAYLAR_T5_1000B:1171-09-13:0":{"b": ["Fatimid rule in Egypt ended, the Ayyubids came to power — Alexandria, the Fayyum and Mecca (Hejaz)", "1c565534"], "d": ["With Saladin's vizierate and the death of the Fatimid caliph al-ʿĀḍid (567/1171), Egypt passed to the Ayyubids; Alexandria and the Fayyum came under Ayyubid administration. The day is not in the source — it was taken over from the end of the Fatimid register entry (the künye date is not a source). The Hejaz also came under Ayyubid administration; the suzerainty of Mecca passed from the Fatimids to the Ayyubids (Emre #23 suzerain model).", "191ac5be"]},
"OLAYLAR_T5_1000B:1174-01-01:0":{"b": ["Saladin took Damascus", "dfdb11ce"], "d": ["After Nūr al-Dīn's death the city passed to Saladin the Ayyubid.", "a20855b8"]},
"OLAYLAR_T5_1000B:1175-07-22:0":{"b": ["The Ayyubids took Aden, the Zurayʿids came to an end", "d253acf0"], "d": ["The Ayyubids advanced on Aden and executed the vizier Yāsir b. Bilāl.", "06e4a877"]},
"OLAYLAR_T5_1000B:1176-09-17:0":{"b": ["After Myriokephalon, Byzantium evacuated Dorylaeum", "24aef255"], "d": ["After the defeat at Myriokephalon, Manuel, in accordance with the treaty, demolished the fortifications of Dorylaeum and evacuated the city; the Turks began to call it Eskişehir.", "d56a7724"]},
"OLAYLAR_T5_1000B:1178-01-01:0":{"b": ["Amasya was joined to Seljuk lands", "cf56b964"], "d": ["Kılıcarslan II joined the Danishmendid lands (including Amasya) to the Seljuk realm.", "ddbb98aa"]},
"OLAYLAR_T5_1000B:1187-01-01:0":{"b": ["The Asen brothers took Northern Bulgaria; Byzantium recognised the Second Bulgarian State", "ff0554e9"], "d": ["The brothers Petar and Asen retook Northern Bulgaria with Cuman support; with the peace of 1187 Byzantium recognised the Second Bulgarian State.", "fc165cbf"]},
"OLAYLAR_T5_1000B:1189-01-01:0":{"b": ["Serbia consolidated its rule in Zeta", "794c821d"], "d": ["In 1189 Serbia consolidated its rule over Zeta (including the Kotor coast); Zeta was granted a special status.", "5f16f312"]},
"OLAYLAR_T5_1000B:1192-01-01:0":{"b": ["Guy de Lusignan bought Cyprus, Nicosia became the capital", "11017aea"], "d": ["Guy de Lusignan bought the island from the Templars and made Nicosia the capital.", "b6494b99"]},
"OLAYLAR_T5_1000B:1201-03-01:0":{"b": ["Kaloyan seized Varna", "1237fe7f"], "d": ["The Bulgarians under Tsar Kaloyan took Varna from Byzantium in March 1201; the city remained within the borders of the Bulgarian State in the 13th-14th centuries.", "b60444f8"]},
"OLAYLAR_T5_1000B:1202-01-01:0":{"b": ["Nishapur was definitively joined to the Khwarazmshahs", "fa4a6cd2"], "d": ["ʿAlāʾ al-Dīn Muhammad b. Tekish definitively joined the city to Khwarazmshah lands.", "58cb9059"]},
"OLAYLAR_T5_1000B:1204-04-13:0":{"b": ["The Gallipoli peninsula came under Latin administration", "27308f59"], "d": ["After the Fourth Crusade, Gallipoli and its surroundings passed to the administration of the Latins in 1204.", "48b977ad"]},
"OLAYLAR_T5_1000B:1204-04-13:1":{"b": ["The Despotate of Epirus was founded — Ioannina became the centre, Lepanto passed to the despotate", "d7966877"], "d": ["After the Fourth Crusade, Michael Angelos founded the Despotate of Epirus; Ioannina was made the centre of the despotate, and Lepanto also remained within the lands of the despotate.", "632eac4c"]},
"OLAYLAR_T5_1000B:1204-08-12:0":{"b": ["Crete was sold to Venice", "f1760e84"], "d": ["Boniface, Marquis of Montferrat, ceded Crete to Venice for 100,000 silver (marks) by the agreement of 12 August 1204.", "cdb2570d"]},
"OLAYLAR_T5_1000B:1219-01-01:0":{"b": ["Mansura was founded", "342a6f47"], "d": ["Al-Malik al-Kāmil founded Mansura as a camp against the Crusaders who had occupied Damietta.", "35189819"]},
"OLAYLAR_T5_1000B:1221-04-10:0":{"b": ["The Mongols took Nishapur", "0e73f075"], "d": ["The city was destroyed in the Mongol invasion.", "be55c768"]},
"OLAYLAR_T5_1000B:1229-01-01:0":{"b": ["The Rasulid Nūr al-Dīn ʿUmar brought Yemen under his rule", "ee1ec7ab"], "d": ["After the death of the last Yemeni Ayyubid, al-Masʿūd, Nūr al-Dīn ʿUmar became master of Yemen.", "02cf9719"]},
"OLAYLAR_T5_1000B:1235-01-01:0":{"b": ["The Emperor of Nicaea Vatatzes retook Gallipoli", "a6936e33"], "d": ["The Emperor of Nicaea, John III Vatatzes, retook Gallipoli from the Latins (1235).", "184a089e"]},
"OLAYLAR_T5_1000B:1243-07-01:0":{"b": ["The Mongols seized Amasya", "783bcd0c"], "d": ["After Köse Dağ the Mongols took the city, and Mongol governors administered it.", "4e46e2df"]},
"OLAYLAR_T5_1000B:1246-01-01:0":{"b": ["Vatatzes crossed into Thrace: Adrianople and Thessalonica were joined to the Empire of Nicaea", "0bf61ca5"], "d": ["The ruler of Nicaea, John III Vatatzes, crossed into Thrace in 1246 and seized the lands occupied by the Bulgarians and Thessalonica.", "73992921"]},
"OLAYLAR_T5_1000B:1250-01-01:0":{"b": ["Rasulid rule was recognised in Mecca — Nūr al-Dīn ʿUmar fell victim to an assassination", "d7e03c21"], "d": ["When the Rasulid Sultan of Yemen Nūr al-Dīn ʿUmar was killed in Janad (February 1250), the rule of his state was recognised between Mecca and Hadramawt; in the year the Ayyubid sultanate ended, Mecca appears under Rasulid suzerainty.", "ba654624"]},
"OLAYLAR_T5_1000B:1250-04-30:0":{"b": ["The Mamluk State was founded in Egypt — Alexandria, Mansura and the Fayyum passed to the Mamluks", "230c1a11"], "d": ["After Turanshah, Mamluk power was established with Shajar al-Durr and ʿIzz al-Dīn Aybak; the Egyptian cities (Alexandria, Mansura, the Fayyum) passed to Mamluk administration. The source gives Aybak's accession as 3 July 1250; the atlas took the day over from the end of the Ayyubid register entry (30 April 1250) — the künye date is not a source, and the difference was reported.", "f9743bcd"]},
"OLAYLAR_T5_1000B:1250-04-30:1":{"b": ["The Ayyubid of Aleppo, al-Nāṣir Yūsuf, became master of Damascus", "d585985d"], "d": ["While Mamluk power was being established in Egypt, the ruler of Aleppo, al-Nāṣir Yūsuf, took Damascus (648/1250).", "c05ddddc"]},
"OLAYLAR_T5_1000B:1253-04-01:0":{"b": ["Jerusalem was left to the Mamluks by peace", "50d53fac"], "d": ["By a peace made through the mediation of the caliph, Jerusalem was left to the Mamluks.", "82982e3a"]},
"OLAYLAR_T5_1000B:1256-01-01:0":{"b": ["Jerusalem passed to the Ayyubids again", "fdeedd4a"], "d": ["Palestine and Jerusalem again fell into the hands of the Ayyubids of Syria.", "46a6e2a9"]},
"OLAYLAR_T5_1000B:1260-03-01:0":{"b": ["The Mongols took Damascus", "430bdfea"], "d": ["In Hülegü's Syrian campaign Damascus passed to the Mongols.", "407e5d3f"]},
"OLAYLAR_T5_1000B:1260-09-03:0":{"b": ["The Battle of ʿAyn Jālūt: Damascus and Jerusalem passed to the Mamluks", "40ebd7b7"], "d": ["Qutuz defeated the Mongols at ʿAyn Jālūt (25 Ramadan 658 / 3 September 1260); the greater part of Syria, Damascus and Jerusalem fell into the hands of the Mamluks, and the Ayyubid dynasty came to an end.", "619c8015"]},
"OLAYLAR_T5_1000B:1261-06-09:0":{"b": ["Baybars revived the Abbasid caliphate in Cairo — Mecca and Medina were attached to the Mamluks", "a5128a1e"], "d": ["Baybars proclaimed in Cairo as caliph the Abbasid Ahmad, who had survived the destruction of Baghdad, and swore allegiance to him; as patron of the caliphate he also bound the Haramayn to Mamluk suzerainty. The day is that of the revival of the caliphate; the day of the attachment of Mecca and Medina is not in the source (lower bound).", "638d550a"]},
"OLAYLAR_T5_1000B:1261-07-25:0":{"b": ["Nicaean troops entered Constantinople — the Byzantine Empire was re-established", "81741490"], "d": ["Nicaean troops entered Constantinople on 25 July 1261, ending Latin rule; the lands of the Laskaris (Nicaea) state — Bursa, İzmir, Çimpe, Adrianople, Thessalonica — became the Byzantine Empire again. At these points the atlas shows the period of the Empire of Nicaea before 1261 only for those that are named in the source.", "b389b508"]},
"OLAYLAR_T5_1000B:1271-01-01:0":{"b": ["Charles of Anjou took Durrës and Krujë", "082a86b8"], "d": ["Charles of the House of Anjou took Durrës and Krujë in 1271-1272 and had the old fortress rebuilt.", "e9f84d14"]},
"OLAYLAR_T5_1000B:1284-01-01:0":{"b": ["The Sicilians occupied the island of Djerba", "daab5ad2"], "d": ["The island of Djerba was occupied by the Sicilians in the year 683 (1284-85); it was first a possession of the papacy, then attached to the Kingdom of Sicily.", "691035b3"]},
"OLAYLAR_T5_1000B:1318-01-01:0":{"b": ["Ioannina was again joined to the Byzantine Empire", "60016303"], "d": ["Ioannina, which changed hands many times in the second half of the 13th century, was again joined to Byzantium in 1318, but preserved its autonomy to a certain degree; the centre of the Despotate of Epirus shifted to Arta.", "14c24d12"]},
"OLAYLAR_T5_1000B:1334-01-01:0":{"b": ["The people of Djerba expelled the Sicilians from the island", "ff71985e"], "d": ["The people of the island, rising against the misrule of the Sicilian governors, expelled the Sicilians in 1334; Djerba came again under Hafsid administration.", "1ddb9780"]},
"OLAYLAR_T5_1000B:1363-01-01:0":{"b": ["Charles Thopia became master of Krujë", "4e40583d"], "d": ["After the death of Tsar Dušan (1355), the Albanian Charles Thopia became master of Krujë.", "7af64cd2"]}
});
